#!/usr/bin/env python3
"""Run and install the development-PC Wayfinder Codex coordinator."""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timedelta
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
from typing import IO
import xml.etree.ElementTree as ET

if os.name == "nt":
    import msvcrt


TASK_NAME = "Codex Wayfinder Autopilot"
TASK_XML_NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"
SCHEDULER_CLEANUP_GRACE_SECONDS = 300
QUEUE_SCOPE_PATTERN = re.compile(r"^(?:user|org):[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$")
HISTORY_RUNS_DIR = "runs"
HISTORY_STATE_OK = "ok"


@dataclass
class AutopilotConfig:
    workspace: Path
    worktree_root: Path
    log_dir: Path
    skill_source: Path
    codex_command: list[str]
    queue_scopes: list[str]
    control_repository: str
    trusted_repository_roots: list[Path]
    upstream_skills_root: Path | None = None
    interval_minutes: int = 15
    timeout_seconds: int = 14_400

    @classmethod
    def load(cls, workspace: Path, config_path: Path | None = None) -> "AutopilotConfig":
        workspace = workspace.resolve()
        path = config_path or workspace / "config" / "wayfinder-autopilot.json"
        with path.open("r", encoding="utf-8") as handle:
            raw = json.load(handle)
        worktree_root = Path(raw.get("worktree_root", "../homelab-worktrees"))
        if not worktree_root.is_absolute():
            worktree_root = workspace / worktree_root
        local_app_data = Path(os.environ.get("LOCALAPPDATA", tempfile.gettempdir()))
        log_dir = Path(raw.get("log_dir", local_app_data / "Codex" / "wayfinder-autopilot"))
        if not log_dir.is_absolute():
            log_dir = workspace / log_dir
        command = raw.get("codex_command", ["codex.cmd"])
        if not isinstance(command, list) or not all(isinstance(item, str) for item in command):
            raise ValueError("codex_command must be a list of strings")
        queue_scopes = raw.get("queue_scopes")
        if (
            not isinstance(queue_scopes, list)
            or not queue_scopes
            or not all(isinstance(scope, str) and QUEUE_SCOPE_PATTERN.fullmatch(scope) for scope in queue_scopes)
        ):
            raise ValueError("each queue scope must be user:<owner> or org:<owner>")
        control_repository = raw.get("control_repository")
        if not isinstance(control_repository, str) or control_repository.count("/") != 1:
            raise ValueError("control_repository must be an owner/repository name")
        trusted_roots = raw.get("trusted_repository_roots", ["repos"])
        if not isinstance(trusted_roots, list) or not all(isinstance(root, str) for root in trusted_roots):
            raise ValueError("trusted_repository_roots must be a list of paths")
        return cls(
            workspace=workspace,
            worktree_root=worktree_root.resolve(),
            log_dir=log_dir.resolve(),
            skill_source=workspace / "skills" / "wayfinder-autopilot",
            codex_command=command,
            queue_scopes=queue_scopes,
            control_repository=control_repository,
            trusted_repository_roots=[
                (workspace / root).resolve() if not Path(root).is_absolute() else Path(root).resolve()
                for root in trusted_roots
            ],
            upstream_skills_root=(
                Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
                / "skills"
            ),
            interval_minutes=int(raw.get("interval_minutes", 15)),
            timeout_seconds=int(raw.get("timeout_seconds", 14_400)),
        )


def upstream_skill_paths(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    root = config.upstream_skills_root or (
        Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve() / "skills"
    )
    return {name: root / name / "SKILL.md" for name in names}


def require_upstream_skill_files(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    paths = upstream_skill_paths(config, names)
    invalid = []
    for name, path in paths.items():
        try:
            source = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            invalid.append(name)
            continue
        frontmatter = re.match(r"\A---\s*\n(.*?)\n---\s*\n(.+)\Z", source, re.DOTALL)
        if not frontmatter or not re.search(
            rf"^name:\s*[\"']?{re.escape(name)}[\"']?\s*$",
            frontmatter.group(1),
            re.MULTILINE,
        ):
            invalid.append(name)
    if invalid:
        raise RuntimeError(
            "required upstream Matt Pocock skills are unavailable or invalid: "
            + ", ".join(invalid)
        )
    return paths


def _issue_route(issue: dict) -> str:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    if any(pr.get("state") == "OPEN" for pr in issue.get("linkedPullRequests", [])):
        return "review"
    return "research" if "wayfinder:research" in labels else "task"


def _has_ticket_contract(issue: dict) -> bool:
    body = issue.get("body", "")
    for heading in ("Outcome", "Completion criteria"):
        section = re.search(
            rf"^## {re.escape(heading)}\s*$\n(.*?)(?=^## |\Z)",
            body,
            re.MULTILINE | re.DOTALL,
        )
        if not section or not section.group(1).strip():
            return False
    return True


def _issue_facts(issue: dict, viewer: str | None) -> dict:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    assignees = {
        node["login"] for node in issue.get("assignees", {}).get("nodes", [])
    }
    markers = [
        comment.get("createdAt") or ""
        for comment in issue.get("comments", {}).get("nodes", [])
        if comment.get("author", {}).get("login") == viewer
        and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
    ]
    return {
        "labels": labels,
        "assignees": assignees,
        "markers": markers,
        "typed": bool(labels & {"wayfinder:research", "wayfinder:task"}),
        "blockers_closed": all(
            blocker.get("state") == "CLOSED"
            for blocker in issue.get("blockedBy", {}).get("nodes", [])
        ),
        "contract": _has_ticket_contract(issue),
    }


def select_snapshot_route(snapshot: dict) -> dict | None:
    viewer = snapshot.get("viewer", {}).get("login")
    issues = snapshot.get("issues", [])

    resumable = []
    for index, issue in enumerate(issues):
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and facts["typed"]
            and "ready-for-human" not in facts["labels"]
            and facts["markers"]
        ):
            resumable.append((min(facts["markers"]), index, issue))
    if resumable:
        issue = min(resumable, key=lambda item: (item[0], item[1]))[2]
        return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and not facts["markers"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and not facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}
    return None


def route_skill_names(route: dict | None) -> tuple[str, ...]:
    if route is None:
        return ()
    if route["phase"] == "research":
        return ("wayfinder", "research")
    if route["phase"] == "review":
        return ("wayfinder", "code-review", "implement", "tdd")
    return ("wayfinder", "implement", "tdd")


class RunLock:
    """A process-held Windows byte lock that cannot become stale."""

    def __init__(self, path: Path):
        self.path = path
        self.handle: IO[bytes] | None = None
        self.acquired = False

    def __enter__(self) -> "RunLock":
        if os.name != "nt":
            raise RuntimeError("Wayfinder autopilot currently supports Windows only")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.handle = self.path.open("a+b")
        self.handle.seek(0, os.SEEK_END)
        if self.handle.tell() == 0:
            self.handle.write(b"0")
            self.handle.flush()
        self.handle.seek(0)
        try:
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_NBLCK, 1)
            self.acquired = True
        except OSError:
            self.acquired = False
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        if self.handle is None:
            return
        if self.acquired:
            self.handle.seek(0)
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_UNLCK, 1)
        self.handle.close()


def build_prompt(
    config: AutopilotConfig,
    dry_run: bool = False,
    queue_snapshot: dict | None = None,
) -> str:
    route = select_snapshot_route(queue_snapshot or {})
    upstream = upstream_skill_paths(config, route_skill_names(route))
    upstream_sources = "\n".join(
        f"- ${name}: {path}" for name, path in upstream.items()
    )
    snapshot_text = f"QUEUE_SNAPSHOT_JSON\n{json.dumps(queue_snapshot, indent=2)}"
    if dry_run:
        action = (
            "Perform a read-only queue dry run. Identify the work item that would be processed "
            "and explain why it is eligible. Do not assign or unassign issues, do not edit labels, "
            "branches, files, pull requests, or parent maps, and do not dispatch server work. "
            "Do not access GitHub or the network; use only the live read-only queue snapshot below."
        )
    else:
        action = (
            "Advance exactly one autonomous unit of work from the exhaustive queue snapshot below. "
            "Treat it as authoritative for discovery and ordering; revalidate only the selected issue "
            "against live GitHub before mutation. Prefer completing review, CI repair, and merge for "
            "an already claimed item before claiming new work."
        )
    return (
        f"Use $wayfinder-autopilot across GitHub scopes {', '.join(config.queue_scopes)}. "
        "Its canonical source is "
        f"{config.skill_source / 'SKILL.md'}; read that authoritative file before acting.\n\n"
        f"PRESELECTED_ROUTE_JSON\n{json.dumps(route, indent=2)}\n\n"
        "Use only the installed upstream Matt Pocock skills named below. Read their current "
        "files directly and follow them as the authoritative workflow sources.\n"
        f"{upstream_sources or '- No upstream phase skill is required for an empty queue.'}\n\n"
        f"{action}\n\n{snapshot_text}\n\n"
        "The development PC is the coordinator. Delegate only server-local investigation or "
        "execution through $server-codex-task, retrieve its result, and continue the same ticket."
    )


def build_codex_command(
    config: AutopilotConfig,
    final_message: Path,
    dry_run: bool = False,
) -> list[str]:
    command = [
        *config.codex_command,
        "exec",
        "--ephemeral",
        "--json",
        "--color",
        "never",
    ]
    if dry_run:
        command.extend(["--sandbox", "read-only"])
    else:
        command.extend(
            [
                "--approve-for-me",
                "--add-dir",
                str(config.worktree_root),
                "--config",
                "sandbox_workspace_write.network_access=true",
            ]
        )
    command.extend(["--cd", str(config.workspace), "-o", str(final_message), "-"])
    return command


def github_token(runner=subprocess.run) -> str:
    completed = runner(
        ["gh", "auth", "token"], capture_output=True, text=True, check=False
    )
    token = completed.stdout.strip()
    if completed.returncode or not token:
        raise RuntimeError("GitHub CLI authentication is unavailable; run gh auth login")
    return token


VIEWER_QUERY = "query { viewer { login } }"

ISSUE_PARENT_QUERY = """
query($id: ID!) {
  node(id: $id) {
    ... on Issue {
      parent { number title url repository { nameWithOwner } }
    }
  }
}
""".strip()


def _run_json(command: list[str], environment: dict[str, str], runner) -> object:
    completed = runner(
        command,
        capture_output=True,
        text=True,
        check=False,
        env=environment,
    )
    if completed.returncode:
        raise RuntimeError(completed.stderr.strip() or "GitHub queue snapshot failed")
    return json.loads(completed.stdout)


def _flatten_pages(value: object) -> list[dict]:
    if not isinstance(value, list):
        raise ValueError("paginated GitHub response must be a list")
    flattened = []
    for page in value:
        if not isinstance(page, list):
            raise ValueError("paginated GitHub response page must be a list")
        flattened.extend(page)
    return flattened


def _repository_from_issue_response(issue: dict) -> str:
    repository_url = issue.get("repository_url", "")
    marker = "/repos/"
    if marker in repository_url:
        return repository_url.split(marker, 1)[1]
    html_parts = issue.get("html_url", "").split("/")
    if len(html_parts) >= 5 and html_parts[2] == "github.com":
        return f"{html_parts[3]}/{html_parts[4]}"
    raise ValueError(f"issue #{issue.get('number')} has no resolvable repository URL")


def load_issue_details(
    summary: dict,
    environment: dict[str, str],
    runner=subprocess.run,
) -> dict:
    repository = summary["repository"]["nameWithOwner"]
    number = summary["number"]
    endpoint = f"repos/{repository}/issues/{number}"
    core = _run_json(["gh", "api", endpoint], environment, runner)
    comments = _flatten_pages(
        _run_json(
            ["gh", "api", "--paginate", "--slurp", f"{endpoint}/comments?per_page=100"],
            environment,
            runner,
        )
    )
    blockers = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                f"{endpoint}/dependencies/blocked_by?per_page=100",
            ],
            environment,
            runner,
        )
    )
    timeline = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                "-H",
                "Accept: application/vnd.github+json",
                f"{endpoint}/timeline?per_page=100",
            ],
            environment,
            runner,
        )
    )
    parent_result = _run_json(
        [
            "gh",
            "api",
            "graphql",
            "-f",
            f"query={ISSUE_PARENT_QUERY}",
            "-f",
            f"id={core['node_id']}",
        ],
        environment,
        runner,
    )
    claim_comments = [
        {
            "body": comment.get("body", ""),
            "author": {"login": (comment.get("user") or {}).get("login")},
            "createdAt": comment.get("created_at"),
        }
        for comment in comments
        if "<!-- wayfinder-autopilot-" in comment.get("body", "")
    ]
    linked_prs = []
    for event in timeline:
        if event.get("event") != "cross-referenced":
            continue
        source_issue = (event.get("source") or {}).get("issue") or {}
        if "pull_request" not in source_issue:
            continue
        linked_prs.append(
            {
                "number": source_issue.get("number"),
                "state": source_issue.get("state", "").upper(),
                "url": source_issue.get("html_url"),
                "repository": {
                    "nameWithOwner": (source_issue.get("repository") or {}).get("full_name")
                },
            }
        )
    return {
        "number": core["number"],
        "title": core["title"],
        "state": core["state"].upper(),
        "body": core.get("body") or "",
        "url": core["html_url"],
        "createdAt": core["created_at"],
        "updatedAt": core["updated_at"],
        "repository": {"nameWithOwner": repository},
        "assignees": {
            "nodes": [{"login": assignee["login"]} for assignee in core.get("assignees", [])]
        },
        "labels": {"nodes": [{"name": label["name"]} for label in core.get("labels", [])]},
        "blockedBy": {
            "nodes": [
                {
                    "number": blocker["number"],
                    "state": blocker["state"].upper(),
                    "repository": {
                        "nameWithOwner": _repository_from_issue_response(blocker)
                    },
                }
                for blocker in blockers
            ]
        },
        "comments": {"nodes": claim_comments},
        "linkedPullRequests": linked_prs,
        "parent": parent_result["data"]["node"]["parent"],
    }


def load_queue_snapshot(
    config: AutopilotConfig,
    token: str,
    runner=subprocess.run,
    detail_loader=None,
) -> dict:
    environment = dict(os.environ)
    environment["GH_TOKEN"] = token
    viewer_result = _run_json(
        ["gh", "api", "graphql", "-f", f"query={VIEWER_QUERY}"],
        environment,
        runner,
    )
    viewer = viewer_result["data"]["viewer"]["login"]
    repositories_by_name = {}
    for scope in config.queue_scopes:
        owner = scope.split(":", 1)[1]
        repositories = _run_json(
            [
                "gh",
                "repo",
                "list",
                owner,
                "--limit",
                "100000",
                "--json",
                "nameWithOwner,isArchived,hasIssuesEnabled",
            ],
            environment,
            runner,
        )
        for repository in repositories:
            if not repository["isArchived"] and repository["hasIssuesEnabled"]:
                repositories_by_name[repository["nameWithOwner"]] = repository

    summaries_by_url = {}
    for repository_name in sorted(repositories_by_name, key=str.lower):
        commands = [
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--assignee", viewer, "--limit", "100000", "--json", "number,url,createdAt",
            ],
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--label", "ready-for-agent", "--limit", "100000", "--json", "number,url,createdAt",
            ],
        ]
        for command in commands:
            for summary in _run_json(command, environment, runner):
                summary["repository"] = {"nameWithOwner": repository_name}
                summaries_by_url[summary["url"]] = summary

    loader = detail_loader or (
        lambda summary: load_issue_details(summary, environment, runner=runner)
    )
    issues = []
    for summary in summaries_by_url.values():
        issue = loader(summary)
        labels = {label["name"] for label in issue["labels"]["nodes"]}
        has_current_claim = any(
            comment.get("author", {}).get("login") == viewer
            and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
            for comment in issue["comments"]["nodes"]
        )
        if "ready-for-agent" in labels or has_current_claim:
            issues.append(issue)
    issues.sort(
        key=lambda issue: (
            issue.get("createdAt", ""),
            issue["repository"]["nameWithOwner"].lower(),
            issue["number"],
        )
    )
    return {
        "viewer": {"login": viewer},
        "scopes": config.queue_scopes,
        "ordering": "createdAt ascending, then repository name, then issue number",
        "issues": issues,
    }


def build_environment(
    config: AutopilotConfig,
    token: str | None,
    base: dict[str, str] | None = None,
) -> dict[str, str]:
    environment = dict(os.environ if base is None else base)
    environment["WAYFINDER_WORKSPACE_ROOT"] = str(config.workspace)
    environment["WAYFINDER_WORKTREE_ROOT"] = str(config.worktree_root)
    environment["WAYFINDER_QUEUE_SCOPES"] = json.dumps(config.queue_scopes)
    environment["WAYFINDER_CONTROL_REPOSITORY"] = config.control_repository
    environment["WAYFINDER_TRUSTED_REPOSITORY_ROOTS"] = json.dumps(
        [str(root) for root in config.trusted_repository_roots]
    )
    environment.pop("GH_TOKEN", None)
    environment.pop("GITHUB_TOKEN", None)
    if token is not None:
        environment["GH_TOKEN"] = token
    environment["GIT_CONFIG_COUNT"] = "2"
    environment["GIT_CONFIG_KEY_0"] = "credential.helper"
    environment["GIT_CONFIG_VALUE_0"] = ""
    environment["GIT_CONFIG_KEY_1"] = "credential.https://github.com.helper"
    environment["GIT_CONFIG_VALUE_1"] = "!gh auth git-credential"
    return environment


def _element(parent: ET.Element, name: str, text: str | None = None) -> ET.Element:
    child = ET.SubElement(parent, f"{{{TASK_XML_NS}}}{name}")
    if text is not None:
        child.text = text
    return child


def render_task_xml(config: AutopilotConfig, user_id: str) -> str:
    ET.register_namespace("", TASK_XML_NS)
    task = ET.Element(f"{{{TASK_XML_NS}}}Task", {"version": "1.4"})
    registration = _element(task, "RegistrationInfo")
    _element(registration, "Description", "Advance trusted Wayfinder work with Codex")
    triggers = _element(task, "Triggers")
    calendar = _element(triggers, "CalendarTrigger")
    repetition = _element(calendar, "Repetition")
    _element(repetition, "Interval", f"PT{config.interval_minutes}M")
    _element(repetition, "Duration", "P1D")
    _element(repetition, "StopAtDurationEnd", "false")
    _element(calendar, "StartBoundary", (datetime.now().astimezone() + timedelta(minutes=1)).isoformat(timespec="seconds"))
    _element(calendar, "Enabled", "true")
    schedule = _element(calendar, "ScheduleByDay")
    _element(schedule, "DaysInterval", "1")
    principals = _element(task, "Principals")
    principal = _element(principals, "Principal")
    principal.set("id", "Author")
    _element(principal, "UserId", user_id)
    _element(principal, "LogonType", "InteractiveToken")
    _element(principal, "RunLevel", "LeastPrivilege")
    settings = _element(task, "Settings")
    _element(settings, "MultipleInstancesPolicy", "IgnoreNew")
    _element(settings, "DisallowStartIfOnBatteries", "false")
    _element(settings, "StopIfGoingOnBatteries", "false")
    _element(settings, "StartWhenAvailable", "true")
    _element(settings, "AllowHardTerminate", "true")
    scheduler_timeout = config.timeout_seconds + SCHEDULER_CLEANUP_GRACE_SECONDS
    hours, remainder = divmod(scheduler_timeout, 3600)
    minutes, seconds = divmod(remainder, 60)
    duration = "PT"
    if hours:
        duration += f"{hours}H"
    if minutes:
        duration += f"{minutes}M"
    if seconds or duration == "PT":
        duration += f"{seconds}S"
    _element(settings, "ExecutionTimeLimit", duration)
    actions = _element(task, "Actions")
    actions.set("Context", "Author")
    execute = _element(actions, "Exec")
    _element(execute, "Command", os.environ.get("ComSpec", r"C:\Windows\System32\cmd.exe"))
    entrypoint = config.workspace / "scripts" / "wayfinder-autopilot.cmd"
    _element(execute, "Arguments", f'/d /c ""{entrypoint}" run"')
    _element(execute, "WorkingDirectory", str(config.workspace))
    return ET.tostring(task, encoding="unicode")


def _terminate_process_tree(process: subprocess.Popen) -> None:
    if os.name == "nt":
        subprocess.run(
            ["taskkill", "/PID", str(process.pid), "/T", "/F"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
    else:
        process.kill()


def run_once(
    config: AutopilotConfig,
    dry_run: bool = False,
    token_provider=github_token,
    snapshot_provider=load_queue_snapshot,
) -> dict:
    config.log_dir.mkdir(parents=True, exist_ok=True)
    if not dry_run:
        config.worktree_root.mkdir(parents=True, exist_ok=True)
    with RunLock(config.log_dir / "run.lock") as lock:
        if not lock.acquired:
            return {"state": "overlap", "message": "another Wayfinder autopilot run is active"}
        run_id = datetime.now().strftime("%Y%m%dT%H%M%S-%f")
        run_dir = config.log_dir / "runs" / run_id
        run_dir.mkdir(parents=True)
        events_path = run_dir / "events.jsonl"
        stderr_path = run_dir / "stderr.log"
        final_path = run_dir / "final.md"
        metadata_path = run_dir / "run.json"
        metadata = {
            "run_id": run_id,
            "state": "running",
            "dry_run": dry_run,
            "started_at": datetime.now().astimezone().isoformat(),
            "workspace": str(config.workspace),
        }
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        exit_code = None
        process = None
        try:
            token = token_provider()
            snapshot = snapshot_provider(config, token)
            route = select_snapshot_route(snapshot)
            require_upstream_skill_files(config, route_skill_names(route))
            environment = build_environment(config, None if dry_run else token)
            command = build_codex_command(config, final_path, dry_run=dry_run)
            with events_path.open("w", encoding="utf-8") as events, stderr_path.open("w", encoding="utf-8") as errors:
                process = subprocess.Popen(
                    command,
                    cwd=config.workspace,
                    env=environment,
                    stdin=subprocess.PIPE,
                    stdout=events,
                    stderr=errors,
                    text=True,
                )
                process.communicate(
                    build_prompt(config, dry_run=dry_run, queue_snapshot=snapshot),
                    timeout=config.timeout_seconds,
                )
                exit_code = process.returncode
                state = "completed" if process.returncode == 0 else "failed"
        except subprocess.TimeoutExpired:
            if process is not None:
                _terminate_process_tree(process)
                process.wait()
                exit_code = process.returncode
            state = "timed_out"
        except (OSError, RuntimeError, ValueError) as exc:
            state = "failed"
            metadata["error"] = str(exc)
        metadata.update(
            state=state,
            exit_code=exit_code,
            finished_at=datetime.now().astimezone().isoformat(),
        )
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        return {
            "state": state,
            "run_id": run_id,
            "events": str(events_path),
            "stderr": str(stderr_path),
            "final_message": str(final_path),
            "metadata": str(metadata_path),
        }


def install(
    config: AutopilotConfig,
    skill_destination: Path,
    user_id: str,
    runner=subprocess.run,
) -> dict:
    if os.name != "nt":
        raise RuntimeError("Wayfinder autopilot installation currently supports Windows only")
    if not (config.skill_source / "SKILL.md").is_file():
        raise FileNotFoundError(f"skill source is incomplete: {config.skill_source}")
    skill_destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(config.skill_source, skill_destination, dirs_exist_ok=True)
    xml = render_task_xml(config, user_id)
    temporary_path: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-16", suffix=".xml", delete=False
        ) as handle:
            handle.write(xml)
            temporary_path = Path(handle.name)
        command = ["schtasks", "/Create", "/TN", TASK_NAME, "/XML", str(temporary_path), "/F"]
        completed = runner(command, capture_output=True, text=True, check=False)
        if completed.returncode:
            raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    finally:
        if temporary_path is not None and temporary_path.is_file():
            temporary_path.unlink()
    return {"state": "installed", "task": TASK_NAME, "skill": str(skill_destination)}


def remove(
    skill_destination: Path,
    skills_root: Path,
    runner=subprocess.run,
) -> dict:
    destination = skill_destination.resolve()
    root = skills_root.resolve()
    if destination.parent != root or destination.name != "wayfinder-autopilot":
        raise ValueError(f"refusing to remove unexpected skill path: {destination}")
    completed = runner(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        check=False,
    )
    if completed.returncode and "cannot find" not in completed.stderr.lower():
        raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    if destination.is_dir():
        shutil.rmtree(destination)
    return {"state": "removed", "task": TASK_NAME, "skill": str(destination)}


def task_status(runner=subprocess.run) -> dict:
    completed = runner(
        ["schtasks", "/Query", "/TN", TASK_NAME, "/FO", "LIST", "/V"],
        capture_output=True,
        text=True,
        check=False,
    )
    return {
        "state": "installed" if completed.returncode == 0 else "not_installed",
        "task": TASK_NAME,
        "details": completed.stdout.strip() or completed.stderr.strip(),
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--config", type=Path)
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("run")
    subparsers.add_parser("dry-run")
    subparsers.add_parser("install")
    subparsers.add_parser("status")
    subparsers.add_parser("uninstall")
    history_parser = subparsers.add_parser("history")
    history_parser.add_argument("--limit", type=int, default=None)
    history_parser.add_argument("--state", action="append", default=None)
    return parser


def list_runs(config: AutopilotConfig, *, limit: int | None = None, states: list[str] | None = None) -> dict:
    runs_dir = config.log_dir / HISTORY_RUNS_DIR
    entries: list[dict] = []
    if runs_dir.is_dir():
        for child in runs_dir.iterdir():
            if not child.is_dir():
                continue
            metadata_path = child / "run.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                entries.append({
                    "run_id": child.name,
                    "state": "unreadable",
                    "dry_run": None,
                    "started_at": None,
                    "finished_at": None,
                    "duration_seconds": None,
                    "exit_code": None,
                    "error": "failed to parse run.json",
                    "events": None,
                    "stderr": None,
                    "final_message": None,
                    "metadata": str(metadata_path),
                })
                continue
            started = metadata.get("started_at")
            finished = metadata.get("finished_at")
            duration: float | None = None
            if started and finished:
                try:
                    start_dt = datetime.fromisoformat(started)
                    finish_dt = datetime.fromisoformat(finished)
                    duration = round((finish_dt - start_dt).total_seconds(), 3)
                except (ValueError, TypeError):
                    pass
            is_abandoned = False
            if metadata.get("state") == "running" and started:
                try:
                    start_dt = datetime.fromisoformat(started)
                    elapsed = (datetime.now().astimezone() - start_dt).total_seconds()
                    if elapsed > SCHEDULER_CLEANUP_GRACE_SECONDS:
                        is_abandoned = True
                except (ValueError, TypeError):
                    pass
            entry = {
                "run_id": metadata.get("run_id", child.name),
                "state": metadata.get("state", "unknown"),
                "dry_run": metadata.get("dry_run"),
                "started_at": started,
                "finished_at": finished,
                "duration_seconds": duration,
                "exit_code": metadata.get("exit_code"),
                "error": metadata.get("error"),
                "abandoned": is_abandoned,
                "events": child.joinpath("events.jsonl") if (child / "events.jsonl").is_file() else None,
                "stderr": child.joinpath("stderr.log") if (child / "stderr.log").is_file() else None,
                "final_message": child.joinpath("final.md") if (child / "final.md").is_file() else None,
                "metadata": str(metadata_path),
            }
            entries.append(entry)
    # run_id is fixed-width timestamp, so lexicographic reverse == newest first
    entries.sort(key=lambda e: e["run_id"], reverse=True)
    if states:
        entries = [e for e in entries if e["state"] in states]
    if limit is not None:
        entries = entries[:limit]
    return {"state": HISTORY_STATE_OK, "runs": entries}


def main() -> int:
    args = build_parser().parse_args()
    try:
        config = AutopilotConfig.load(args.workspace, args.config)
        codex_home = Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
        skills_root = codex_home / "skills"
        skill_destination = skills_root / "wayfinder-autopilot"
        if args.command in {"run", "dry-run"}:
            result = run_once(config, dry_run=args.command == "dry-run")
        elif args.command == "install":
            user = subprocess.run(
                ["whoami"], capture_output=True, text=True, check=True
            ).stdout.strip()
            result = install(config, skill_destination, user)
        elif args.command == "status":
            result = task_status()
            result["log_dir"] = str(config.log_dir)
            result["skill"] = str(skill_destination)
        elif args.command == "history":
            states = sorted(args.state) if args.state else None
            result = list_runs(config, limit=args.limit, states=states)
        else:
            result = remove(skill_destination, skills_root)
        print(json.dumps(result, indent=2))
        return 0 if result["state"] not in {"failed", "timed_out"} else 1
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError, subprocess.CalledProcessError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Run and install the development-PC Wayfinder Codex coordinator."""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timedelta
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
from typing import IO
import xml.etree.ElementTree as ET

if os.name == "nt":
    import msvcrt


TASK_NAME = "Codex Wayfinder Autopilot"
TASK_XML_NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"
SCHEDULER_CLEANUP_GRACE_SECONDS = 300
QUEUE_SCOPE_PATTERN = re.compile(r"^(?:user|org):[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$")
HISTORY_RUNS_DIR = "runs"
HISTORY_STATE_OK = "ok"


@dataclass
class AutopilotConfig:
    workspace: Path
    worktree_root: Path
    log_dir: Path
    skill_source: Path
    codex_command: list[str]
    queue_scopes: list[str]
    control_repository: str
    trusted_repository_roots: list[Path]
    upstream_skills_root: Path | None = None
    interval_minutes: int = 15
    timeout_seconds: int = 14_400

    @classmethod
    def load(cls, workspace: Path, config_path: Path | None = None) -> "AutopilotConfig":
        workspace = workspace.resolve()
        path = config_path or workspace / "config" / "wayfinder-autopilot.json"
        with path.open("r", encoding="utf-8") as handle:
            raw = json.load(handle)
        worktree_root = Path(raw.get("worktree_root", "../homelab-worktrees"))
        if not worktree_root.is_absolute():
            worktree_root = workspace / worktree_root
        local_app_data = Path(os.environ.get("LOCALAPPDATA", tempfile.gettempdir()))
        log_dir = Path(raw.get("log_dir", local_app_data / "Codex" / "wayfinder-autopilot"))
        if not log_dir.is_absolute():
            log_dir = workspace / log_dir
        command = raw.get("codex_command", ["codex.cmd"])
        if not isinstance(command, list) or not all(isinstance(item, str) for item in command):
            raise ValueError("codex_command must be a list of strings")
        queue_scopes = raw.get("queue_scopes")
        if (
            not isinstance(queue_scopes, list)
            or not queue_scopes
            or not all(isinstance(scope, str) and QUEUE_SCOPE_PATTERN.fullmatch(scope) for scope in queue_scopes)
        ):
            raise ValueError("each queue scope must be user:<owner> or org:<owner>")
        control_repository = raw.get("control_repository")
        if not isinstance(control_repository, str) or control_repository.count("/") != 1:
            raise ValueError("control_repository must be an owner/repository name")
        trusted_roots = raw.get("trusted_repository_roots", ["repos"])
        if not isinstance(trusted_roots, list) or not all(isinstance(root, str) for root in trusted_roots):
            raise ValueError("trusted_repository_roots must be a list of paths")
        return cls(
            workspace=workspace,
            worktree_root=worktree_root.resolve(),
            log_dir=log_dir.resolve(),
            skill_source=workspace / "skills" / "wayfinder-autopilot",
            codex_command=command,
            queue_scopes=queue_scopes,
            control_repository=control_repository,
            trusted_repository_roots=[
                (workspace / root).resolve() if not Path(root).is_absolute() else Path(root).resolve()
                for root in trusted_roots
            ],
            upstream_skills_root=(
                Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
                / "skills"
            ),
            interval_minutes=int(raw.get("interval_minutes", 15)),
            timeout_seconds=int(raw.get("timeout_seconds", 14_400)),
        )


def upstream_skill_paths(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    root = config.upstream_skills_root or (
        Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve() / "skills"
    )
    return {name: root / name / "SKILL.md" for name in names}


def require_upstream_skill_files(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    paths = upstream_skill_paths(config, names)
    invalid = []
    for name, path in paths.items():
        try:
            source = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            invalid.append(name)
            continue
        frontmatter = re.match(r"\A---\s*\n(.*?)\n---\s*\n(.+)\Z", source, re.DOTALL)
        if not frontmatter or not re.search(
            rf"^name:\s*[\"']?{re.escape(name)}[\"']?\s*$",
            frontmatter.group(1),
            re.MULTILINE,
        ):
            invalid.append(name)
    if invalid:
        raise RuntimeError(
            "required upstream Matt Pocock skills are unavailable or invalid: "
            + ", ".join(invalid)
        )
    return paths


def _issue_route(issue: dict) -> str:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    if any(pr.get("state") == "OPEN" for pr in issue.get("linkedPullRequests", [])):
        return "review"
    return "research" if "wayfinder:research" in labels else "task"


def _has_ticket_contract(issue: dict) -> bool:
    body = issue.get("body", "")
    for heading in ("Outcome", "Completion criteria"):
        section = re.search(
            rf"^## {re.escape(heading)}\s*$\n(.*?)(?=^## |\Z)",
            body,
            re.MULTILINE | re.DOTALL,
        )
        if not section or not section.group(1).strip():
            return False
    return True


def _issue_facts(issue: dict, viewer: str | None) -> dict:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    assignees = {
        node["login"] for node in issue.get("assignees", {}).get("nodes", [])
    }
    markers = [
        comment.get("createdAt") or ""
        for comment in issue.get("comments", {}).get("nodes", [])
        if comment.get("author", {}).get("login") == viewer
        and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
    ]
    return {
        "labels": labels,
        "assignees": assignees,
        "markers": markers,
        "typed": bool(labels & {"wayfinder:research", "wayfinder:task"}),
        "blockers_closed": all(
            blocker.get("state") == "CLOSED"
            for blocker in issue.get("blockedBy", {}).get("nodes", [])
        ),
        "contract": _has_ticket_contract(issue),
    }


def select_snapshot_route(snapshot: dict) -> dict | None:
    viewer = snapshot.get("viewer", {}).get("login")
    issues = snapshot.get("issues", [])

    resumable = []
    for index, issue in enumerate(issues):
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and facts["typed"]
            and "ready-for-human" not in facts["labels"]
            and facts["markers"]
        ):
            resumable.append((min(facts["markers"]), index, issue))
    if resumable:
        issue = min(resumable, key=lambda item: (item[0], item[1]))[2]
        return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and not facts["markers"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and not facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}
    return None


def route_skill_names(route: dict | None) -> tuple[str, ...]:
    if route is None:
        return ()
    if route["phase"] == "research":
        return ("wayfinder", "research")
    if route["phase"] == "review":
        return ("wayfinder", "code-review", "implement", "tdd")
    return ("wayfinder", "implement", "tdd")


class RunLock:
    """A process-held Windows byte lock that cannot become stale."""

    def __init__(self, path: Path):
        self.path = path
        self.handle: IO[bytes] | None = None
        self.acquired = False

    def __enter__(self) -> "RunLock":
        if os.name != "nt":
            raise RuntimeError("Wayfinder autopilot currently supports Windows only")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.handle = self.path.open("a+b")
        self.handle.seek(0, os.SEEK_END)
        if self.handle.tell() == 0:
            self.handle.write(b"0")
            self.handle.flush()
        self.handle.seek(0)
        try:
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_NBLCK, 1)
            self.acquired = True
        except OSError:
            self.acquired = False
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        if self.handle is None:
            return
        if self.acquired:
            self.handle.seek(0)
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_UNLCK, 1)
        self.handle.close()


def build_prompt(
    config: AutopilotConfig,
    dry_run: bool = False,
    queue_snapshot: dict | None = None,
) -> str:
    route = select_snapshot_route(queue_snapshot or {})
    upstream = upstream_skill_paths(config, route_skill_names(route))
    upstream_sources = "\n".join(
        f"- ${name}: {path}" for name, path in upstream.items()
    )
    snapshot_text = f"QUEUE_SNAPSHOT_JSON\n{json.dumps(queue_snapshot, indent=2)}"
    if dry_run:
        action = (
            "Perform a read-only queue dry run. Identify the work item that would be processed "
            "and explain why it is eligible. Do not assign or unassign issues, do not edit labels, "
            "branches, files, pull requests, or parent maps, and do not dispatch server work. "
            "Do not access GitHub or the network; use only the live read-only queue snapshot below."
        )
    else:
        action = (
            "Advance exactly one autonomous unit of work from the exhaustive queue snapshot below. "
            "Treat it as authoritative for discovery and ordering; revalidate only the selected issue "
            "against live GitHub before mutation. Prefer completing review, CI repair, and merge for "
            "an already claimed item before claiming new work."
        )
    return (
        f"Use $wayfinder-autopilot across GitHub scopes {', '.join(config.queue_scopes)}. "
        "Its canonical source is "
        f"{config.skill_source / 'SKILL.md'}; read that authoritative file before acting.\n\n"
        f"PRESELECTED_ROUTE_JSON\n{json.dumps(route, indent=2)}\n\n"
        "Use only the installed upstream Matt Pocock skills named below. Read their current "
        "files directly and follow them as the authoritative workflow sources.\n"
        f"{upstream_sources or '- No upstream phase skill is required for an empty queue.'}\n\n"
        f"{action}\n\n{snapshot_text}\n\n"
        "The development PC is the coordinator. Delegate only server-local investigation or "
        "execution through $server-codex-task, retrieve its result, and continue the same ticket."
    )


def build_codex_command(
    config: AutopilotConfig,
    final_message: Path,
    dry_run: bool = False,
) -> list[str]:
    command = [
        *config.codex_command,
        "exec",
        "--ephemeral",
        "--json",
        "--color",
        "never",
    ]
    if dry_run:
        command.extend(["--sandbox", "read-only"])
    else:
        command.extend(
            [
                "--approve-for-me",
                "--add-dir",
                str(config.worktree_root),
                "--config",
                "sandbox_workspace_write.network_access=true",
            ]
        )
    command.extend(["--cd", str(config.workspace), "-o", str(final_message), "-"])
    return command


def github_token(runner=subprocess.run) -> str:
    completed = runner(
        ["gh", "auth", "token"], capture_output=True, text=True, check=False
    )
    token = completed.stdout.strip()
    if completed.returncode or not token:
        raise RuntimeError("GitHub CLI authentication is unavailable; run gh auth login")
    return token


VIEWER_QUERY = "query { viewer { login } }"

ISSUE_PARENT_QUERY = """
query($id: ID!) {
  node(id: $id) {
    ... on Issue {
      parent { number title url repository { nameWithOwner } }
    }
  }
}
""".strip()


def _run_json(command: list[str], environment: dict[str, str], runner) -> object:
    completed = runner(
        command,
        capture_output=True,
        text=True,
        check=False,
        env=environment,
    )
    if completed.returncode:
        raise RuntimeError(completed.stderr.strip() or "GitHub queue snapshot failed")
    return json.loads(completed.stdout)


def _flatten_pages(value: object) -> list[dict]:
    if not isinstance(value, list):
        raise ValueError("paginated GitHub response must be a list")
    flattened = []
    for page in value:
        if not isinstance(page, list):
            raise ValueError("paginated GitHub response page must be a list")
        flattened.extend(page)
    return flattened


def _repository_from_issue_response(issue: dict) -> str:
    repository_url = issue.get("repository_url", "")
    marker = "/repos/"
    if marker in repository_url:
        return repository_url.split(marker, 1)[1]
    html_parts = issue.get("html_url", "").split("/")
    if len(html_parts) >= 5 and html_parts[2] == "github.com":
        return f"{html_parts[3]}/{html_parts[4]}"
    raise ValueError(f"issue #{issue.get('number')} has no resolvable repository URL")


def load_issue_details(
    summary: dict,
    environment: dict[str, str],
    runner=subprocess.run,
) -> dict:
    repository = summary["repository"]["nameWithOwner"]
    number = summary["number"]
    endpoint = f"repos/{repository}/issues/{number}"
    core = _run_json(["gh", "api", endpoint], environment, runner)
    comments = _flatten_pages(
        _run_json(
            ["gh", "api", "--paginate", "--slurp", f"{endpoint}/comments?per_page=100"],
            environment,
            runner,
        )
    )
    blockers = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                f"{endpoint}/dependencies/blocked_by?per_page=100",
            ],
            environment,
            runner,
        )
    )
    timeline = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                "-H",
                "Accept: application/vnd.github+json",
                f"{endpoint}/timeline?per_page=100",
            ],
            environment,
            runner,
        )
    )
    parent_result = _run_json(
        [
            "gh",
            "api",
            "graphql",
            "-f",
            f"query={ISSUE_PARENT_QUERY}",
            "-f",
            f"id={core['node_id']}",
        ],
        environment,
        runner,
    )
    claim_comments = [
        {
            "body": comment.get("body", ""),
            "author": {"login": (comment.get("user") or {}).get("login")},
            "createdAt": comment.get("created_at"),
        }
        for comment in comments
        if "<!-- wayfinder-autopilot-" in comment.get("body", "")
    ]
    linked_prs = []
    for event in timeline:
        if event.get("event") != "cross-referenced":
            continue
        source_issue = (event.get("source") or {}).get("issue") or {}
        if "pull_request" not in source_issue:
            continue
        linked_prs.append(
            {
                "number": source_issue.get("number"),
                "state": source_issue.get("state", "").upper(),
                "url": source_issue.get("html_url"),
                "repository": {
                    "nameWithOwner": (source_issue.get("repository") or {}).get("full_name")
                },
            }
        )
    return {
        "number": core["number"],
        "title": core["title"],
        "state": core["state"].upper(),
        "body": core.get("body") or "",
        "url": core["html_url"],
        "createdAt": core["created_at"],
        "updatedAt": core["updated_at"],
        "repository": {"nameWithOwner": repository},
        "assignees": {
            "nodes": [{"login": assignee["login"]} for assignee in core.get("assignees", [])]
        },
        "labels": {"nodes": [{"name": label["name"]} for label in core.get("labels", [])]},
        "blockedBy": {
            "nodes": [
                {
                    "number": blocker["number"],
                    "state": blocker["state"].upper(),
                    "repository": {
                        "nameWithOwner": _repository_from_issue_response(blocker)
                    },
                }
                for blocker in blockers
            ]
        },
        "comments": {"nodes": claim_comments},
        "linkedPullRequests": linked_prs,
        "parent": parent_result["data"]["node"]["parent"],
    }


def load_queue_snapshot(
    config: AutopilotConfig,
    token: str,
    runner=subprocess.run,
    detail_loader=None,
) -> dict:
    environment = dict(os.environ)
    environment["GH_TOKEN"] = token
    viewer_result = _run_json(
        ["gh", "api", "graphql", "-f", f"query={VIEWER_QUERY}"],
        environment,
        runner,
    )
    viewer = viewer_result["data"]["viewer"]["login"]
    repositories_by_name = {}
    for scope in config.queue_scopes:
        owner = scope.split(":", 1)[1]
        repositories = _run_json(
            [
                "gh",
                "repo",
                "list",
                owner,
                "--limit",
                "100000",
                "--json",
                "nameWithOwner,isArchived,hasIssuesEnabled",
            ],
            environment,
            runner,
        )
        for repository in repositories:
            if not repository["isArchived"] and repository["hasIssuesEnabled"]:
                repositories_by_name[repository["nameWithOwner"]] = repository

    summaries_by_url = {}
    for repository_name in sorted(repositories_by_name, key=str.lower):
        commands = [
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--assignee", viewer, "--limit", "100000", "--json", "number,url,createdAt",
            ],
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--label", "ready-for-agent", "--limit", "100000", "--json", "number,url,createdAt",
            ],
        ]
        for command in commands:
            for summary in _run_json(command, environment, runner):
                summary["repository"] = {"nameWithOwner": repository_name}
                summaries_by_url[summary["url"]] = summary

    loader = detail_loader or (
        lambda summary: load_issue_details(summary, environment, runner=runner)
    )
    issues = []
    for summary in summaries_by_url.values():
        issue = loader(summary)
        labels = {label["name"] for label in issue["labels"]["nodes"]}
        has_current_claim = any(
            comment.get("author", {}).get("login") == viewer
            and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
            for comment in issue["comments"]["nodes"]
        )
        if "ready-for-agent" in labels or has_current_claim:
            issues.append(issue)
    issues.sort(
        key=lambda issue: (
            issue.get("createdAt", ""),
            issue["repository"]["nameWithOwner"].lower(),
            issue["number"],
        )
    )
    return {
        "viewer": {"login": viewer},
        "scopes": config.queue_scopes,
        "ordering": "createdAt ascending, then repository name, then issue number",
        "issues": issues,
    }


def build_environment(
    config: AutopilotConfig,
    token: str | None,
    base: dict[str, str] | None = None,
) -> dict[str, str]:
    environment = dict(os.environ if base is None else base)
    environment["WAYFINDER_WORKSPACE_ROOT"] = str(config.workspace)
    environment["WAYFINDER_WORKTREE_ROOT"] = str(config.worktree_root)
    environment["WAYFINDER_QUEUE_SCOPES"] = json.dumps(config.queue_scopes)
    environment["WAYFINDER_CONTROL_REPOSITORY"] = config.control_repository
    environment["WAYFINDER_TRUSTED_REPOSITORY_ROOTS"] = json.dumps(
        [str(root) for root in config.trusted_repository_roots]
    )
    environment.pop("GH_TOKEN", None)
    environment.pop("GITHUB_TOKEN", None)
    if token is not None:
        environment["GH_TOKEN"] = token
    environment["GIT_CONFIG_COUNT"] = "2"
    environment["GIT_CONFIG_KEY_0"] = "credential.helper"
    environment["GIT_CONFIG_VALUE_0"] = ""
    environment["GIT_CONFIG_KEY_1"] = "credential.https://github.com.helper"
    environment["GIT_CONFIG_VALUE_1"] = "!gh auth git-credential"
    return environment


def _element(parent: ET.Element, name: str, text: str | None = None) -> ET.Element:
    child = ET.SubElement(parent, f"{{{TASK_XML_NS}}}{name}")
    if text is not None:
        child.text = text
    return child


def render_task_xml(config: AutopilotConfig, user_id: str) -> str:
    ET.register_namespace("", TASK_XML_NS)
    task = ET.Element(f"{{{TASK_XML_NS}}}Task", {"version": "1.4"})
    registration = _element(task, "RegistrationInfo")
    _element(registration, "Description", "Advance trusted Wayfinder work with Codex")
    triggers = _element(task, "Triggers")
    calendar = _element(triggers, "CalendarTrigger")
    repetition = _element(calendar, "Repetition")
    _element(repetition, "Interval", f"PT{config.interval_minutes}M")
    _element(repetition, "Duration", "P1D")
    _element(repetition, "StopAtDurationEnd", "false")
    _element(calendar, "StartBoundary", (datetime.now().astimezone() + timedelta(minutes=1)).isoformat(timespec="seconds"))
    _element(calendar, "Enabled", "true")
    schedule = _element(calendar, "ScheduleByDay")
    _element(schedule, "DaysInterval", "1")
    principals = _element(task, "Principals")
    principal = _element(principals, "Principal")
    principal.set("id", "Author")
    _element(principal, "UserId", user_id)
    _element(principal, "LogonType", "InteractiveToken")
    _element(principal, "RunLevel", "LeastPrivilege")
    settings = _element(task, "Settings")
    _element(settings, "MultipleInstancesPolicy", "IgnoreNew")
    _element(settings, "DisallowStartIfOnBatteries", "false")
    _element(settings, "StopIfGoingOnBatteries", "false")
    _element(settings, "StartWhenAvailable", "true")
    _element(settings, "AllowHardTerminate", "true")
    scheduler_timeout = config.timeout_seconds + SCHEDULER_CLEANUP_GRACE_SECONDS
    hours, remainder = divmod(scheduler_timeout, 3600)
    minutes, seconds = divmod(remainder, 60)
    duration = "PT"
    if hours:
        duration += f"{hours}H"
    if minutes:
        duration += f"{minutes}M"
    if seconds or duration == "PT":
        duration += f"{seconds}S"
    _element(settings, "ExecutionTimeLimit", duration)
    actions = _element(task, "Actions")
    actions.set("Context", "Author")
    execute = _element(actions, "Exec")
    _element(execute, "Command", os.environ.get("ComSpec", r"C:\Windows\System32\cmd.exe"))
    entrypoint = config.workspace / "scripts" / "wayfinder-autopilot.cmd"
    _element(execute, "Arguments", f'/d /c ""{entrypoint}" run"')
    _element(execute, "WorkingDirectory", str(config.workspace))
    return ET.tostring(task, encoding="unicode")


def _terminate_process_tree(process: subprocess.Popen) -> None:
    if os.name == "nt":
        subprocess.run(
            ["taskkill", "/PID", str(process.pid), "/T", "/F"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
    else:
        process.kill()


def run_once(
    config: AutopilotConfig,
    dry_run: bool = False,
    token_provider=github_token,
    snapshot_provider=load_queue_snapshot,
) -> dict:
    config.log_dir.mkdir(parents=True, exist_ok=True)
    if not dry_run:
        config.worktree_root.mkdir(parents=True, exist_ok=True)
    with RunLock(config.log_dir / "run.lock") as lock:
        if not lock.acquired:
            return {"state": "overlap", "message": "another Wayfinder autopilot run is active"}
        run_id = datetime.now().strftime("%Y%m%dT%H%M%S-%f")
        run_dir = config.log_dir / "runs" / run_id
        run_dir.mkdir(parents=True)
        events_path = run_dir / "events.jsonl"
        stderr_path = run_dir / "stderr.log"
        final_path = run_dir / "final.md"
        metadata_path = run_dir / "run.json"
        metadata = {
            "run_id": run_id,
            "state": "running",
            "dry_run": dry_run,
            "started_at": datetime.now().astimezone().isoformat(),
            "workspace": str(config.workspace),
        }
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        exit_code = None
        process = None
        try:
            token = token_provider()
            snapshot = snapshot_provider(config, token)
            route = select_snapshot_route(snapshot)
            require_upstream_skill_files(config, route_skill_names(route))
            environment = build_environment(config, None if dry_run else token)
            command = build_codex_command(config, final_path, dry_run=dry_run)
            with events_path.open("w", encoding="utf-8") as events, stderr_path.open("w", encoding="utf-8") as errors:
                process = subprocess.Popen(
                    command,
                    cwd=config.workspace,
                    env=environment,
                    stdin=subprocess.PIPE,
                    stdout=events,
                    stderr=errors,
                    text=True,
                )
                process.communicate(
                    build_prompt(config, dry_run=dry_run, queue_snapshot=snapshot),
                    timeout=config.timeout_seconds,
                )
                exit_code = process.returncode
                state = "completed" if process.returncode == 0 else "failed"
        except subprocess.TimeoutExpired:
            if process is not None:
                _terminate_process_tree(process)
                process.wait()
                exit_code = process.returncode
            state = "timed_out"
        except (OSError, RuntimeError, ValueError) as exc:
            state = "failed"
            metadata["error"] = str(exc)
        metadata.update(
            state=state,
            exit_code=exit_code,
            finished_at=datetime.now().astimezone().isoformat(),
        )
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        return {
            "state": state,
            "run_id": run_id,
            "events": str(events_path),
            "stderr": str(stderr_path),
            "final_message": str(final_path),
            "metadata": str(metadata_path),
        }


def install(
    config: AutopilotConfig,
    skill_destination: Path,
    user_id: str,
    runner=subprocess.run,
) -> dict:
    if os.name != "nt":
        raise RuntimeError("Wayfinder autopilot installation currently supports Windows only")
    if not (config.skill_source / "SKILL.md").is_file():
        raise FileNotFoundError(f"skill source is incomplete: {config.skill_source}")
    skill_destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(config.skill_source, skill_destination, dirs_exist_ok=True)
    xml = render_task_xml(config, user_id)
    temporary_path: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-16", suffix=".xml", delete=False
        ) as handle:
            handle.write(xml)
            temporary_path = Path(handle.name)
        command = ["schtasks", "/Create", "/TN", TASK_NAME, "/XML", str(temporary_path), "/F"]
        completed = runner(command, capture_output=True, text=True, check=False)
        if completed.returncode:
            raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    finally:
        if temporary_path is not None and temporary_path.is_file():
            temporary_path.unlink()
    return {"state": "installed", "task": TASK_NAME, "skill": str(skill_destination)}


def remove(
    skill_destination: Path,
    skills_root: Path,
    runner=subprocess.run,
) -> dict:
    destination = skill_destination.resolve()
    root = skills_root.resolve()
    if destination.parent != root or destination.name != "wayfinder-autopilot":
        raise ValueError(f"refusing to remove unexpected skill path: {destination}")
    completed = runner(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        check=False,
    )
    if completed.returncode and "cannot find" not in completed.stderr.lower():
        raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    if destination.is_dir():
        shutil.rmtree(destination)
    return {"state": "removed", "task": TASK_NAME, "skill": str(destination)}


def task_status(runner=subprocess.run) -> dict:
    completed = runner(
        ["schtasks", "/Query", "/TN", TASK_NAME, "/FO", "LIST", "/V"],
        capture_output=True,
        text=True,
        check=False,
    )
    return {
        "state": "installed" if completed.returncode == 0 else "not_installed",
        "task": TASK_NAME,
        "details": completed.stdout.strip() or completed.stderr.strip(),
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--config", type=Path)
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("run")
    subparsers.add_parser("dry-run")
    subparsers.add_parser("install")
    subparsers.add_parser("status")
    subparsers.add_parser("uninstall")
    history_parser = subparsers.add_parser("history")
    history_parser.add_argument("--limit", type=int, default=None)
    history_parser.add_argument("--state", action="append", default=None)
    return parser


def list_runs(config: AutopilotConfig, *, limit: int | None = None, states: list[str] | None = None) -> dict:
    runs_dir = config.log_dir / HISTORY_RUNS_DIR
    entries: list[dict] = []
    if runs_dir.is_dir():
        for child in runs_dir.iterdir():
            if not child.is_dir():
                continue
            metadata_path = child / "run.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                entries.append({
                    "run_id": child.name,
                    "state": "unreadable",
                    "dry_run": None,
                    "started_at": None,
                    "finished_at": None,
                    "duration_seconds": None,
                    "exit_code": None,
                    "error": "failed to parse run.json",
                    "events": None,
                    "stderr": None,
                    "final_message": None,
                    "metadata": str(metadata_path),
                })
                continue
            started = metadata.get("started_at")
            finished = metadata.get("finished_at")
            duration: float | None = None
            if started and finished:
                try:
                    start_dt = datetime.fromisoformat(started)
                    finish_dt = datetime.fromisoformat(finished)
                    duration = round((finish_dt - start_dt).total_seconds(), 3)
                except (ValueError, TypeError):
                    pass
            is_abandoned = False
            if metadata.get("state") == "running" and started:
                try:
                    start_dt = datetime.fromisoformat(started)
                    elapsed = (datetime.now().astimezone() - start_dt).total_seconds()
                    if elapsed > SCHEDULER_CLEANUP_GRACE_SECONDS:
                        is_abandoned = True
                except (ValueError, TypeError):
                    pass
            entry = {
                "run_id": metadata.get("run_id", child.name),
                "state": metadata.get("state", "unknown"),
                "dry_run": metadata.get("dry_run"),
                "started_at": started,
                "finished_at": finished,
                "duration_seconds": duration,
                "exit_code": metadata.get("exit_code"),
                "error": metadata.get("error"),
                "abandoned": is_abandoned,
                "events": child.joinpath("events.jsonl") if (child / "events.jsonl").is_file() else None,
                "stderr": child.joinpath("stderr.log") if (child / "stderr.log").is_file() else None,
                "final_message": child.joinpath("final.md") if (child / "final.md").is_file() else None,
                "metadata": str(metadata_path),
            }
            entries.append(entry)
    # run_id is fixed-width timestamp, so lexicographic reverse == newest first
    entries.sort(key=lambda e: e["run_id"], reverse=True)
    if states:
        entries = [e for e in entries if e["state"] in states]
    if limit is not None:
        entries = entries[:limit]
    return {"state": HISTORY_STATE_OK, "runs": entries}


def main() -> int:
    args = build_parser().parse_args()
    try:
        config = AutopilotConfig.load(args.workspace, args.config)
        codex_home = Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
        skills_root = codex_home / "skills"
        skill_destination = skills_root / "wayfinder-autopilot"
        if args.command in {"run", "dry-run"}:
            result = run_once(config, dry_run=args.command == "dry-run")
        elif args.command == "install":
            user = subprocess.run(
                ["whoami"], capture_output=True, text=True, check=True
            ).stdout.strip()
            result = install(config, skill_destination, user)
        elif args.command == "status":
            result = task_status()
            result["log_dir"] = str(config.log_dir)
            result["skill"] = str(skill_destination)
        elif args.command == "history":
            states = sorted(args.state) if args.state else None
            result = list_runs(config, limit=args.limit, states=states)
        else:
            result = remove(skill_destination, skills_root)
        print(json.dumps(result, indent=2))
        return 0 if result["state"] not in {"failed", "timed_out"} else 1
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError, subprocess.CalledProcessError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Run and install the development-PC Wayfinder Codex coordinator."""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timedelta
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
from typing import IO
import xml.etree.ElementTree as ET

if os.name == "nt":
    import msvcrt


TASK_NAME = "Codex Wayfinder Autopilot"
TASK_XML_NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"
SCHEDULER_CLEANUP_GRACE_SECONDS = 300
QUEUE_SCOPE_PATTERN = re.compile(r"^(?:user|org):[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$")
HISTORY_RUNS_DIR = "runs"
HISTORY_STATE_OK = "ok"


@dataclass
class AutopilotConfig:
    workspace: Path
    worktree_root: Path
    log_dir: Path
    skill_source: Path
    codex_command: list[str]
    queue_scopes: list[str]
    control_repository: str
    trusted_repository_roots: list[Path]
    upstream_skills_root: Path | None = None
    interval_minutes: int = 15
    timeout_seconds: int = 14_400

    @classmethod
    def load(cls, workspace: Path, config_path: Path | None = None) -> "AutopilotConfig":
        workspace = workspace.resolve()
        path = config_path or workspace / "config" / "wayfinder-autopilot.json"
        with path.open("r", encoding="utf-8") as handle:
            raw = json.load(handle)
        worktree_root = Path(raw.get("worktree_root", "../homelab-worktrees"))
        if not worktree_root.is_absolute():
            worktree_root = workspace / worktree_root
        local_app_data = Path(os.environ.get("LOCALAPPDATA", tempfile.gettempdir()))
        log_dir = Path(raw.get("log_dir", local_app_data / "Codex" / "wayfinder-autopilot"))
        if not log_dir.is_absolute():
            log_dir = workspace / log_dir
        command = raw.get("codex_command", ["codex.cmd"])
        if not isinstance(command, list) or not all(isinstance(item, str) for item in command):
            raise ValueError("codex_command must be a list of strings")
        queue_scopes = raw.get("queue_scopes")
        if (
            not isinstance(queue_scopes, list)
            or not queue_scopes
            or not all(isinstance(scope, str) and QUEUE_SCOPE_PATTERN.fullmatch(scope) for scope in queue_scopes)
        ):
            raise ValueError("each queue scope must be user:<owner> or org:<owner>")
        control_repository = raw.get("control_repository")
        if not isinstance(control_repository, str) or control_repository.count("/") != 1:
            raise ValueError("control_repository must be an owner/repository name")
        trusted_roots = raw.get("trusted_repository_roots", ["repos"])
        if not isinstance(trusted_roots, list) or not all(isinstance(root, str) for root in trusted_roots):
            raise ValueError("trusted_repository_roots must be a list of paths")
        return cls(
            workspace=workspace,
            worktree_root=worktree_root.resolve(),
            log_dir=log_dir.resolve(),
            skill_source=workspace / "skills" / "wayfinder-autopilot",
            codex_command=command,
            queue_scopes=queue_scopes,
            control_repository=control_repository,
            trusted_repository_roots=[
                (workspace / root).resolve() if not Path(root).is_absolute() else Path(root).resolve()
                for root in trusted_roots
            ],
            upstream_skills_root=(
                Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
                / "skills"
            ),
            interval_minutes=int(raw.get("interval_minutes", 15)),
            timeout_seconds=int(raw.get("timeout_seconds", 14_400)),
        )


def upstream_skill_paths(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    root = config.upstream_skills_root or (
        Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve() / "skills"
    )
    return {name: root / name / "SKILL.md" for name in names}


def require_upstream_skill_files(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    paths = upstream_skill_paths(config, names)
    invalid = []
    for name, path in paths.items():
        try:
            source = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            invalid.append(name)
            continue
        frontmatter = re.match(r"\A---\s*\n(.*?)\n---\s*\n(.+)\Z", source, re.DOTALL)
        if not frontmatter or not re.search(
            rf"^name:\s*[\"']?{re.escape(name)}[\"']?\s*$",
            frontmatter.group(1),
            re.MULTILINE,
        ):
            invalid.append(name)
    if invalid:
        raise RuntimeError(
            "required upstream Matt Pocock skills are unavailable or invalid: "
            + ", ".join(invalid)
        )
    return paths


def _issue_route(issue: dict) -> str:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    if any(pr.get("state") == "OPEN" for pr in issue.get("linkedPullRequests", [])):
        return "review"
    return "research" if "wayfinder:research" in labels else "task"


def _has_ticket_contract(issue: dict) -> bool:
    body = issue.get("body", "")
    for heading in ("Outcome", "Completion criteria"):
        section = re.search(
            rf"^## {re.escape(heading)}\s*$\n(.*?)(?=^## |\Z)",
            body,
            re.MULTILINE | re.DOTALL,
        )
        if not section or not section.group(1).strip():
            return False
    return True


def _issue_facts(issue: dict, viewer: str | None) -> dict:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    assignees = {
        node["login"] for node in issue.get("assignees", {}).get("nodes", [])
    }
    markers = [
        comment.get("createdAt") or ""
        for comment in issue.get("comments", {}).get("nodes", [])
        if comment.get("author", {}).get("login") == viewer
        and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
    ]
    return {
        "labels": labels,
        "assignees": assignees,
        "markers": markers,
        "typed": bool(labels & {"wayfinder:research", "wayfinder:task"}),
        "blockers_closed": all(
            blocker.get("state") == "CLOSED"
            for blocker in issue.get("blockedBy", {}).get("nodes", [])
        ),
        "contract": _has_ticket_contract(issue),
    }


def select_snapshot_route(snapshot: dict) -> dict | None:
    viewer = snapshot.get("viewer", {}).get("login")
    issues = snapshot.get("issues", [])

    resumable = []
    for index, issue in enumerate(issues):
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and facts["typed"]
            and "ready-for-human" not in facts["labels"]
            and facts["markers"]
        ):
            resumable.append((min(facts["markers"]), index, issue))
    if resumable:
        issue = min(resumable, key=lambda item: (item[0], item[1]))[2]
        return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and not facts["markers"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and not facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}
    return None


def route_skill_names(route: dict | None) -> tuple[str, ...]:
    if route is None:
        return ()
    if route["phase"] == "research":
        return ("wayfinder", "research")
    if route["phase"] == "review":
        return ("wayfinder", "code-review", "implement", "tdd")
    return ("wayfinder", "implement", "tdd")


class RunLock:
    """A process-held Windows byte lock that cannot become stale."""

    def __init__(self, path: Path):
        self.path = path
        self.handle: IO[bytes] | None = None
        self.acquired = False

    def __enter__(self) -> "RunLock":
        if os.name != "nt":
            raise RuntimeError("Wayfinder autopilot currently supports Windows only")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.handle = self.path.open("a+b")
        self.handle.seek(0, os.SEEK_END)
        if self.handle.tell() == 0:
            self.handle.write(b"0")
            self.handle.flush()
        self.handle.seek(0)
        try:
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_NBLCK, 1)
            self.acquired = True
        except OSError:
            self.acquired = False
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        if self.handle is None:
            return
        if self.acquired:
            self.handle.seek(0)
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_UNLCK, 1)
        self.handle.close()


def build_prompt(
    config: AutopilotConfig,
    dry_run: bool = False,
    queue_snapshot: dict | None = None,
) -> str:
    route = select_snapshot_route(queue_snapshot or {})
    upstream = upstream_skill_paths(config, route_skill_names(route))
    upstream_sources = "\n".join(
        f"- ${name}: {path}" for name, path in upstream.items()
    )
    snapshot_text = f"QUEUE_SNAPSHOT_JSON\n{json.dumps(queue_snapshot, indent=2)}"
    if dry_run:
        action = (
            "Perform a read-only queue dry run. Identify the work item that would be processed "
            "and explain why it is eligible. Do not assign or unassign issues, do not edit labels, "
            "branches, files, pull requests, or parent maps, and do not dispatch server work. "
            "Do not access GitHub or the network; use only the live read-only queue snapshot below."
        )
    else:
        action = (
            "Advance exactly one autonomous unit of work from the exhaustive queue snapshot below. "
            "Treat it as authoritative for discovery and ordering; revalidate only the selected issue "
            "against live GitHub before mutation. Prefer completing review, CI repair, and merge for "
            "an already claimed item before claiming new work."
        )
    return (
        f"Use $wayfinder-autopilot across GitHub scopes {', '.join(config.queue_scopes)}. "
        "Its canonical source is "
        f"{config.skill_source / 'SKILL.md'}; read that authoritative file before acting.\n\n"
        f"PRESELECTED_ROUTE_JSON\n{json.dumps(route, indent=2)}\n\n"
        "Use only the installed upstream Matt Pocock skills named below. Read their current "
        "files directly and follow them as the authoritative workflow sources.\n"
        f"{upstream_sources or '- No upstream phase skill is required for an empty queue.'}\n\n"
        f"{action}\n\n{snapshot_text}\n\n"
        "The development PC is the coordinator. Delegate only server-local investigation or "
        "execution through $server-codex-task, retrieve its result, and continue the same ticket."
    )


def build_codex_command(
    config: AutopilotConfig,
    final_message: Path,
    dry_run: bool = False,
) -> list[str]:
    command = [
        *config.codex_command,
        "exec",
        "--ephemeral",
        "--json",
        "--color",
        "never",
    ]
    if dry_run:
        command.extend(["--sandbox", "read-only"])
    else:
        command.extend(
            [
                "--approve-for-me",
                "--add-dir",
                str(config.worktree_root),
                "--config",
                "sandbox_workspace_write.network_access=true",
            ]
        )
    command.extend(["--cd", str(config.workspace), "-o", str(final_message), "-"])
    return command


def github_token(runner=subprocess.run) -> str:
    completed = runner(
        ["gh", "auth", "token"], capture_output=True, text=True, check=False
    )
    token = completed.stdout.strip()
    if completed.returncode or not token:
        raise RuntimeError("GitHub CLI authentication is unavailable; run gh auth login")
    return token


VIEWER_QUERY = "query { viewer { login } }"

ISSUE_PARENT_QUERY = """
query($id: ID!) {
  node(id: $id) {
    ... on Issue {
      parent { number title url repository { nameWithOwner } }
    }
  }
}
""".strip()


def _run_json(command: list[str], environment: dict[str, str], runner) -> object:
    completed = runner(
        command,
        capture_output=True,
        text=True,
        check=False,
        env=environment,
    )
    if completed.returncode:
        raise RuntimeError(completed.stderr.strip() or "GitHub queue snapshot failed")
    return json.loads(completed.stdout)


def _flatten_pages(value: object) -> list[dict]:
    if not isinstance(value, list):
        raise ValueError("paginated GitHub response must be a list")
    flattened = []
    for page in value:
        if not isinstance(page, list):
            raise ValueError("paginated GitHub response page must be a list")
        flattened.extend(page)
    return flattened


def _repository_from_issue_response(issue: dict) -> str:
    repository_url = issue.get("repository_url", "")
    marker = "/repos/"
    if marker in repository_url:
        return repository_url.split(marker, 1)[1]
    html_parts = issue.get("html_url", "").split("/")
    if len(html_parts) >= 5 and html_parts[2] == "github.com":
        return f"{html_parts[3]}/{html_parts[4]}"
    raise ValueError(f"issue #{issue.get('number')} has no resolvable repository URL")


def load_issue_details(
    summary: dict,
    environment: dict[str, str],
    runner=subprocess.run,
) -> dict:
    repository = summary["repository"]["nameWithOwner"]
    number = summary["number"]
    endpoint = f"repos/{repository}/issues/{number}"
    core = _run_json(["gh", "api", endpoint], environment, runner)
    comments = _flatten_pages(
        _run_json(
            ["gh", "api", "--paginate", "--slurp", f"{endpoint}/comments?per_page=100"],
            environment,
            runner,
        )
    )
    blockers = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                f"{endpoint}/dependencies/blocked_by?per_page=100",
            ],
            environment,
            runner,
        )
    )
    timeline = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                "-H",
                "Accept: application/vnd.github+json",
                f"{endpoint}/timeline?per_page=100",
            ],
            environment,
            runner,
        )
    )
    parent_result = _run_json(
        [
            "gh",
            "api",
            "graphql",
            "-f",
            f"query={ISSUE_PARENT_QUERY}",
            "-f",
            f"id={core['node_id']}",
        ],
        environment,
        runner,
    )
    claim_comments = [
        {
            "body": comment.get("body", ""),
            "author": {"login": (comment.get("user") or {}).get("login")},
            "createdAt": comment.get("created_at"),
        }
        for comment in comments
        if "<!-- wayfinder-autopilot-" in comment.get("body", "")
    ]
    linked_prs = []
    for event in timeline:
        if event.get("event") != "cross-referenced":
            continue
        source_issue = (event.get("source") or {}).get("issue") or {}
        if "pull_request" not in source_issue:
            continue
        linked_prs.append(
            {
                "number": source_issue.get("number"),
                "state": source_issue.get("state", "").upper(),
                "url": source_issue.get("html_url"),
                "repository": {
                    "nameWithOwner": (source_issue.get("repository") or {}).get("full_name")
                },
            }
        )
    return {
        "number": core["number"],
        "title": core["title"],
        "state": core["state"].upper(),
        "body": core.get("body") or "",
        "url": core["html_url"],
        "createdAt": core["created_at"],
        "updatedAt": core["updated_at"],
        "repository": {"nameWithOwner": repository},
        "assignees": {
            "nodes": [{"login": assignee["login"]} for assignee in core.get("assignees", [])]
        },
        "labels": {"nodes": [{"name": label["name"]} for label in core.get("labels", [])]},
        "blockedBy": {
            "nodes": [
                {
                    "number": blocker["number"],
                    "state": blocker["state"].upper(),
                    "repository": {
                        "nameWithOwner": _repository_from_issue_response(blocker)
                    },
                }
                for blocker in blockers
            ]
        },
        "comments": {"nodes": claim_comments},
        "linkedPullRequests": linked_prs,
        "parent": parent_result["data"]["node"]["parent"],
    }


def load_queue_snapshot(
    config: AutopilotConfig,
    token: str,
    runner=subprocess.run,
    detail_loader=None,
) -> dict:
    environment = dict(os.environ)
    environment["GH_TOKEN"] = token
    viewer_result = _run_json(
        ["gh", "api", "graphql", "-f", f"query={VIEWER_QUERY}"],
        environment,
        runner,
    )
    viewer = viewer_result["data"]["viewer"]["login"]
    repositories_by_name = {}
    for scope in config.queue_scopes:
        owner = scope.split(":", 1)[1]
        repositories = _run_json(
            [
                "gh",
                "repo",
                "list",
                owner,
                "--limit",
                "100000",
                "--json",
                "nameWithOwner,isArchived,hasIssuesEnabled",
            ],
            environment,
            runner,
        )
        for repository in repositories:
            if not repository["isArchived"] and repository["hasIssuesEnabled"]:
                repositories_by_name[repository["nameWithOwner"]] = repository

    summaries_by_url = {}
    for repository_name in sorted(repositories_by_name, key=str.lower):
        commands = [
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--assignee", viewer, "--limit", "100000", "--json", "number,url,createdAt",
            ],
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--label", "ready-for-agent", "--limit", "100000", "--json", "number,url,createdAt",
            ],
        ]
        for command in commands:
            for summary in _run_json(command, environment, runner):
                summary["repository"] = {"nameWithOwner": repository_name}
                summaries_by_url[summary["url"]] = summary

    loader = detail_loader or (
        lambda summary: load_issue_details(summary, environment, runner=runner)
    )
    issues = []
    for summary in summaries_by_url.values():
        issue = loader(summary)
        labels = {label["name"] for label in issue["labels"]["nodes"]}
        has_current_claim = any(
            comment.get("author", {}).get("login") == viewer
            and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
            for comment in issue["comments"]["nodes"]
        )
        if "ready-for-agent" in labels or has_current_claim:
            issues.append(issue)
    issues.sort(
        key=lambda issue: (
            issue.get("createdAt", ""),
            issue["repository"]["nameWithOwner"].lower(),
            issue["number"],
        )
    )
    return {
        "viewer": {"login": viewer},
        "scopes": config.queue_scopes,
        "ordering": "createdAt ascending, then repository name, then issue number",
        "issues": issues,
    }


def build_environment(
    config: AutopilotConfig,
    token: str | None,
    base: dict[str, str] | None = None,
) -> dict[str, str]:
    environment = dict(os.environ if base is None else base)
    environment["WAYFINDER_WORKSPACE_ROOT"] = str(config.workspace)
    environment["WAYFINDER_WORKTREE_ROOT"] = str(config.worktree_root)
    environment["WAYFINDER_QUEUE_SCOPES"] = json.dumps(config.queue_scopes)
    environment["WAYFINDER_CONTROL_REPOSITORY"] = config.control_repository
    environment["WAYFINDER_TRUSTED_REPOSITORY_ROOTS"] = json.dumps(
        [str(root) for root in config.trusted_repository_roots]
    )
    environment.pop("GH_TOKEN", None)
    environment.pop("GITHUB_TOKEN", None)
    if token is not None:
        environment["GH_TOKEN"] = token
    environment["GIT_CONFIG_COUNT"] = "2"
    environment["GIT_CONFIG_KEY_0"] = "credential.helper"
    environment["GIT_CONFIG_VALUE_0"] = ""
    environment["GIT_CONFIG_KEY_1"] = "credential.https://github.com.helper"
    environment["GIT_CONFIG_VALUE_1"] = "!gh auth git-credential"
    return environment


def _element(parent: ET.Element, name: str, text: str | None = None) -> ET.Element:
    child = ET.SubElement(parent, f"{{{TASK_XML_NS}}}{name}")
    if text is not None:
        child.text = text
    return child


def render_task_xml(config: AutopilotConfig, user_id: str) -> str:
    ET.register_namespace("", TASK_XML_NS)
    task = ET.Element(f"{{{TASK_XML_NS}}}Task", {"version": "1.4"})
    registration = _element(task, "RegistrationInfo")
    _element(registration, "Description", "Advance trusted Wayfinder work with Codex")
    triggers = _element(task, "Triggers")
    calendar = _element(triggers, "CalendarTrigger")
    repetition = _element(calendar, "Repetition")
    _element(repetition, "Interval", f"PT{config.interval_minutes}M")
    _element(repetition, "Duration", "P1D")
    _element(repetition, "StopAtDurationEnd", "false")
    _element(calendar, "StartBoundary", (datetime.now().astimezone() + timedelta(minutes=1)).isoformat(timespec="seconds"))
    _element(calendar, "Enabled", "true")
    schedule = _element(calendar, "ScheduleByDay")
    _element(schedule, "DaysInterval", "1")
    principals = _element(task, "Principals")
    principal = _element(principals, "Principal")
    principal.set("id", "Author")
    _element(principal, "UserId", user_id)
    _element(principal, "LogonType", "InteractiveToken")
    _element(principal, "RunLevel", "LeastPrivilege")
    settings = _element(task, "Settings")
    _element(settings, "MultipleInstancesPolicy", "IgnoreNew")
    _element(settings, "DisallowStartIfOnBatteries", "false")
    _element(settings, "StopIfGoingOnBatteries", "false")
    _element(settings, "StartWhenAvailable", "true")
    _element(settings, "AllowHardTerminate", "true")
    scheduler_timeout = config.timeout_seconds + SCHEDULER_CLEANUP_GRACE_SECONDS
    hours, remainder = divmod(scheduler_timeout, 3600)
    minutes, seconds = divmod(remainder, 60)
    duration = "PT"
    if hours:
        duration += f"{hours}H"
    if minutes:
        duration += f"{minutes}M"
    if seconds or duration == "PT":
        duration += f"{seconds}S"
    _element(settings, "ExecutionTimeLimit", duration)
    actions = _element(task, "Actions")
    actions.set("Context", "Author")
    execute = _element(actions, "Exec")
    _element(execute, "Command", os.environ.get("ComSpec", r"C:\Windows\System32\cmd.exe"))
    entrypoint = config.workspace / "scripts" / "wayfinder-autopilot.cmd"
    _element(execute, "Arguments", f'/d /c ""{entrypoint}" run"')
    _element(execute, "WorkingDirectory", str(config.workspace))
    return ET.tostring(task, encoding="unicode")


def _terminate_process_tree(process: subprocess.Popen) -> None:
    if os.name == "nt":
        subprocess.run(
            ["taskkill", "/PID", str(process.pid), "/T", "/F"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
    else:
        process.kill()


def run_once(
    config: AutopilotConfig,
    dry_run: bool = False,
    token_provider=github_token,
    snapshot_provider=load_queue_snapshot,
) -> dict:
    config.log_dir.mkdir(parents=True, exist_ok=True)
    if not dry_run:
        config.worktree_root.mkdir(parents=True, exist_ok=True)
    with RunLock(config.log_dir / "run.lock") as lock:
        if not lock.acquired:
            return {"state": "overlap", "message": "another Wayfinder autopilot run is active"}
        run_id = datetime.now().strftime("%Y%m%dT%H%M%S-%f")
        run_dir = config.log_dir / "runs" / run_id
        run_dir.mkdir(parents=True)
        events_path = run_dir / "events.jsonl"
        stderr_path = run_dir / "stderr.log"
        final_path = run_dir / "final.md"
        metadata_path = run_dir / "run.json"
        metadata = {
            "run_id": run_id,
            "state": "running",
            "dry_run": dry_run,
            "started_at": datetime.now().astimezone().isoformat(),
            "workspace": str(config.workspace),
        }
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        exit_code = None
        process = None
        try:
            token = token_provider()
            snapshot = snapshot_provider(config, token)
            route = select_snapshot_route(snapshot)
            require_upstream_skill_files(config, route_skill_names(route))
            environment = build_environment(config, None if dry_run else token)
            command = build_codex_command(config, final_path, dry_run=dry_run)
            with events_path.open("w", encoding="utf-8") as events, stderr_path.open("w", encoding="utf-8") as errors:
                process = subprocess.Popen(
                    command,
                    cwd=config.workspace,
                    env=environment,
                    stdin=subprocess.PIPE,
                    stdout=events,
                    stderr=errors,
                    text=True,
                )
                process.communicate(
                    build_prompt(config, dry_run=dry_run, queue_snapshot=snapshot),
                    timeout=config.timeout_seconds,
                )
                exit_code = process.returncode
                state = "completed" if process.returncode == 0 else "failed"
        except subprocess.TimeoutExpired:
            if process is not None:
                _terminate_process_tree(process)
                process.wait()
                exit_code = process.returncode
            state = "timed_out"
        except (OSError, RuntimeError, ValueError) as exc:
            state = "failed"
            metadata["error"] = str(exc)
        metadata.update(
            state=state,
            exit_code=exit_code,
            finished_at=datetime.now().astimezone().isoformat(),
        )
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        return {
            "state": state,
            "run_id": run_id,
            "events": str(events_path),
            "stderr": str(stderr_path),
            "final_message": str(final_path),
            "metadata": str(metadata_path),
        }


def install(
    config: AutopilotConfig,
    skill_destination: Path,
    user_id: str,
    runner=subprocess.run,
) -> dict:
    if os.name != "nt":
        raise RuntimeError("Wayfinder autopilot installation currently supports Windows only")
    if not (config.skill_source / "SKILL.md").is_file():
        raise FileNotFoundError(f"skill source is incomplete: {config.skill_source}")
    skill_destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(config.skill_source, skill_destination, dirs_exist_ok=True)
    xml = render_task_xml(config, user_id)
    temporary_path: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-16", suffix=".xml", delete=False
        ) as handle:
            handle.write(xml)
            temporary_path = Path(handle.name)
        command = ["schtasks", "/Create", "/TN", TASK_NAME, "/XML", str(temporary_path), "/F"]
        completed = runner(command, capture_output=True, text=True, check=False)
        if completed.returncode:
            raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    finally:
        if temporary_path is not None and temporary_path.is_file():
            temporary_path.unlink()
    return {"state": "installed", "task": TASK_NAME, "skill": str(skill_destination)}


def remove(
    skill_destination: Path,
    skills_root: Path,
    runner=subprocess.run,
) -> dict:
    destination = skill_destination.resolve()
    root = skills_root.resolve()
    if destination.parent != root or destination.name != "wayfinder-autopilot":
        raise ValueError(f"refusing to remove unexpected skill path: {destination}")
    completed = runner(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        check=False,
    )
    if completed.returncode and "cannot find" not in completed.stderr.lower():
        raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    if destination.is_dir():
        shutil.rmtree(destination)
    return {"state": "removed", "task": TASK_NAME, "skill": str(destination)}


def task_status(runner=subprocess.run) -> dict:
    completed = runner(
        ["schtasks", "/Query", "/TN", TASK_NAME, "/FO", "LIST", "/V"],
        capture_output=True,
        text=True,
        check=False,
    )
    return {
        "state": "installed" if completed.returncode == 0 else "not_installed",
        "task": TASK_NAME,
        "details": completed.stdout.strip() or completed.stderr.strip(),
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--config", type=Path)
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("run")
    subparsers.add_parser("dry-run")
    subparsers.add_parser("install")
    subparsers.add_parser("status")
    subparsers.add_parser("uninstall")
    history_parser = subparsers.add_parser("history")
    history_parser.add_argument("--limit", type=int, default=None)
    history_parser.add_argument("--state", action="append", default=None)
    return parser


def list_runs(config: AutopilotConfig, *, limit: int | None = None, states: list[str] | None = None) -> dict:
    runs_dir = config.log_dir / HISTORY_RUNS_DIR
    entries: list[dict] = []
    if runs_dir.is_dir():
        for child in runs_dir.iterdir():
            if not child.is_dir():
                continue
            metadata_path = child / "run.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                entries.append({
                    "run_id": child.name,
                    "state": "unreadable",
                    "dry_run": None,
                    "started_at": None,
                    "finished_at": None,
                    "duration_seconds": None,
                    "exit_code": None,
                    "error": "failed to parse run.json",
                    "events": None,
                    "stderr": None,
                    "final_message": None,
                    "metadata": str(metadata_path),
                })
                continue
            started = metadata.get("started_at")
            finished = metadata.get("finished_at")
            duration: float | None = None
            if started and finished:
                try:
                    start_dt = datetime.fromisoformat(started)
                    finish_dt = datetime.fromisoformat(finished)
                    duration = round((finish_dt - start_dt).total_seconds(), 3)
                except (ValueError, TypeError):
                    pass
            is_abandoned = False
            if metadata.get("state") == "running" and started:
                try:
                    start_dt = datetime.fromisoformat(started)
                    elapsed = (datetime.now().astimezone() - start_dt).total_seconds()
                    if elapsed > SCHEDULER_CLEANUP_GRACE_SECONDS:
                        is_abandoned = True
                except (ValueError, TypeError):
                    pass
            entry = {
                "run_id": metadata.get("run_id", child.name),
                "state": metadata.get("state", "unknown"),
                "dry_run": metadata.get("dry_run"),
                "started_at": started,
                "finished_at": finished,
                "duration_seconds": duration,
                "exit_code": metadata.get("exit_code"),
                "error": metadata.get("error"),
                "abandoned": is_abandoned,
                "events": child.joinpath("events.jsonl") if (child / "events.jsonl").is_file() else None,
                "stderr": child.joinpath("stderr.log") if (child / "stderr.log").is_file() else None,
                "final_message": child.joinpath("final.md") if (child / "final.md").is_file() else None,
                "metadata": str(metadata_path),
            }
            entries.append(entry)
    # run_id is fixed-width timestamp, so lexicographic reverse == newest first
    entries.sort(key=lambda e: e["run_id"], reverse=True)
    if states:
        entries = [e for e in entries if e["state"] in states]
    if limit is not None:
        entries = entries[:limit]
    return {"state": HISTORY_STATE_OK, "runs": entries}


def main() -> int:
    args = build_parser().parse_args()
    try:
        config = AutopilotConfig.load(args.workspace, args.config)
        codex_home = Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
        skills_root = codex_home / "skills"
        skill_destination = skills_root / "wayfinder-autopilot"
        if args.command in {"run", "dry-run"}:
            result = run_once(config, dry_run=args.command == "dry-run")
        elif args.command == "install":
            user = subprocess.run(
                ["whoami"], capture_output=True, text=True, check=True
            ).stdout.strip()
            result = install(config, skill_destination, user)
        elif args.command == "status":
            result = task_status()
            result["log_dir"] = str(config.log_dir)
            result["skill"] = str(skill_destination)
        elif args.command == "history":
            states = sorted(args.state) if args.state else None
            result = list_runs(config, limit=args.limit, states=states)
        else:
            result = remove(skill_destination, skills_root)
        print(json.dumps(result, indent=2))
        return 0 if result["state"] not in {"failed", "timed_out"} else 1
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError, subprocess.CalledProcessError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Run and install the development-PC Wayfinder Codex coordinator."""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timedelta
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
from typing import IO
import xml.etree.ElementTree as ET

if os.name == "nt":
    import msvcrt


TASK_NAME = "Codex Wayfinder Autopilot"
TASK_XML_NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"
SCHEDULER_CLEANUP_GRACE_SECONDS = 300
QUEUE_SCOPE_PATTERN = re.compile(r"^(?:user|org):[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$")
HISTORY_RUNS_DIR = "runs"
HISTORY_STATE_OK = "ok"


@dataclass
class AutopilotConfig:
    workspace: Path
    worktree_root: Path
    log_dir: Path
    skill_source: Path
    codex_command: list[str]
    queue_scopes: list[str]
    control_repository: str
    trusted_repository_roots: list[Path]
    upstream_skills_root: Path | None = None
    interval_minutes: int = 15
    timeout_seconds: int = 14_400

    @classmethod
    def load(cls, workspace: Path, config_path: Path | None = None) -> "AutopilotConfig":
        workspace = workspace.resolve()
        path = config_path or workspace / "config" / "wayfinder-autopilot.json"
        with path.open("r", encoding="utf-8") as handle:
            raw = json.load(handle)
        worktree_root = Path(raw.get("worktree_root", "../homelab-worktrees"))
        if not worktree_root.is_absolute():
            worktree_root = workspace / worktree_root
        local_app_data = Path(os.environ.get("LOCALAPPDATA", tempfile.gettempdir()))
        log_dir = Path(raw.get("log_dir", local_app_data / "Codex" / "wayfinder-autopilot"))
        if not log_dir.is_absolute():
            log_dir = workspace / log_dir
        command = raw.get("codex_command", ["codex.cmd"])
        if not isinstance(command, list) or not all(isinstance(item, str) for item in command):
            raise ValueError("codex_command must be a list of strings")
        queue_scopes = raw.get("queue_scopes")
        if (
            not isinstance(queue_scopes, list)
            or not queue_scopes
            or not all(isinstance(scope, str) and QUEUE_SCOPE_PATTERN.fullmatch(scope) for scope in queue_scopes)
        ):
            raise ValueError("each queue scope must be user:<owner> or org:<owner>")
        control_repository = raw.get("control_repository")
        if not isinstance(control_repository, str) or control_repository.count("/") != 1:
            raise ValueError("control_repository must be an owner/repository name")
        trusted_roots = raw.get("trusted_repository_roots", ["repos"])
        if not isinstance(trusted_roots, list) or not all(isinstance(root, str) for root in trusted_roots):
            raise ValueError("trusted_repository_roots must be a list of paths")
        return cls(
            workspace=workspace,
            worktree_root=worktree_root.resolve(),
            log_dir=log_dir.resolve(),
            skill_source=workspace / "skills" / "wayfinder-autopilot",
            codex_command=command,
            queue_scopes=queue_scopes,
            control_repository=control_repository,
            trusted_repository_roots=[
                (workspace / root).resolve() if not Path(root).is_absolute() else Path(root).resolve()
                for root in trusted_roots
            ],
            upstream_skills_root=(
                Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
                / "skills"
            ),
            interval_minutes=int(raw.get("interval_minutes", 15)),
            timeout_seconds=int(raw.get("timeout_seconds", 14_400)),
        )


def upstream_skill_paths(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    root = config.upstream_skills_root or (
        Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve() / "skills"
    )
    return {name: root / name / "SKILL.md" for name in names}


def require_upstream_skill_files(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    paths = upstream_skill_paths(config, names)
    invalid = []
    for name, path in paths.items():
        try:
            source = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            invalid.append(name)
            continue
        frontmatter = re.match(r"\A---\s*\n(.*?)\n---\s*\n(.+)\Z", source, re.DOTALL)
        if not frontmatter or not re.search(
            rf"^name:\s*[\"']?{re.escape(name)}[\"']?\s*$",
            frontmatter.group(1),
            re.MULTILINE,
        ):
            invalid.append(name)
    if invalid:
        raise RuntimeError(
            "required upstream Matt Pocock skills are unavailable or invalid: "
            + ", ".join(invalid)
        )
    return paths


def _issue_route(issue: dict) -> str:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    if any(pr.get("state") == "OPEN" for pr in issue.get("linkedPullRequests", [])):
        return "review"
    return "research" if "wayfinder:research" in labels else "task"


def _has_ticket_contract(issue: dict) -> bool:
    body = issue.get("body", "")
    for heading in ("Outcome", "Completion criteria"):
        section = re.search(
            rf"^## {re.escape(heading)}\s*$\n(.*?)(?=^## |\Z)",
            body,
            re.MULTILINE | re.DOTALL,
        )
        if not section or not section.group(1).strip():
            return False
    return True


def _issue_facts(issue: dict, viewer: str | None) -> dict:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    assignees = {
        node["login"] for node in issue.get("assignees", {}).get("nodes", [])
    }
    markers = [
        comment.get("createdAt") or ""
        for comment in issue.get("comments", {}).get("nodes", [])
        if comment.get("author", {}).get("login") == viewer
        and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
    ]
    return {
        "labels": labels,
        "assignees": assignees,
        "markers": markers,
        "typed": bool(labels & {"wayfinder:research", "wayfinder:task"}),
        "blockers_closed": all(
            blocker.get("state") == "CLOSED"
            for blocker in issue.get("blockedBy", {}).get("nodes", [])
        ),
        "contract": _has_ticket_contract(issue),
    }


def select_snapshot_route(snapshot: dict) -> dict | None:
    viewer = snapshot.get("viewer", {}).get("login")
    issues = snapshot.get("issues", [])

    resumable = []
    for index, issue in enumerate(issues):
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and facts["typed"]
            and "ready-for-human" not in facts["labels"]
            and facts["markers"]
        ):
            resumable.append((min(facts["markers"]), index, issue))
    if resumable:
        issue = min(resumable, key=lambda item: (item[0], item[1]))[2]
        return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and not facts["markers"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and not facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}
    return None


def route_skill_names(route: dict | None) -> tuple[str, ...]:
    if route is None:
        return ()
    if route["phase"] == "research":
        return ("wayfinder", "research")
    if route["phase"] == "review":
        return ("wayfinder", "code-review", "implement", "tdd")
    return ("wayfinder", "implement", "tdd")


class RunLock:
    """A process-held Windows byte lock that cannot become stale."""

    def __init__(self, path: Path):
        self.path = path
        self.handle: IO[bytes] | None = None
        self.acquired = False

    def __enter__(self) -> "RunLock":
        if os.name != "nt":
            raise RuntimeError("Wayfinder autopilot currently supports Windows only")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.handle = self.path.open("a+b")
        self.handle.seek(0, os.SEEK_END)
        if self.handle.tell() == 0:
            self.handle.write(b"0")
            self.handle.flush()
        self.handle.seek(0)
        try:
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_NBLCK, 1)
            self.acquired = True
        except OSError:
            self.acquired = False
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        if self.handle is None:
            return
        if self.acquired:
            self.handle.seek(0)
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_UNLCK, 1)
        self.handle.close()


def build_prompt(
    config: AutopilotConfig,
    dry_run: bool = False,
    queue_snapshot: dict | None = None,
) -> str:
    route = select_snapshot_route(queue_snapshot or {})
    upstream = upstream_skill_paths(config, route_skill_names(route))
    upstream_sources = "\n".join(
        f"- ${name}: {path}" for name, path in upstream.items()
    )
    snapshot_text = f"QUEUE_SNAPSHOT_JSON\n{json.dumps(queue_snapshot, indent=2)}"
    if dry_run:
        action = (
            "Perform a read-only queue dry run. Identify the work item that would be processed "
            "and explain why it is eligible. Do not assign or unassign issues, do not edit labels, "
            "branches, files, pull requests, or parent maps, and do not dispatch server work. "
            "Do not access GitHub or the network; use only the live read-only queue snapshot below."
        )
    else:
        action = (
            "Advance exactly one autonomous unit of work from the exhaustive queue snapshot below. "
            "Treat it as authoritative for discovery and ordering; revalidate only the selected issue "
            "against live GitHub before mutation. Prefer completing review, CI repair, and merge for "
            "an already claimed item before claiming new work."
        )
    return (
        f"Use $wayfinder-autopilot across GitHub scopes {', '.join(config.queue_scopes)}. "
        "Its canonical source is "
        f"{config.skill_source / 'SKILL.md'}; read that authoritative file before acting.\n\n"
        f"PRESELECTED_ROUTE_JSON\n{json.dumps(route, indent=2)}\n\n"
        "Use only the installed upstream Matt Pocock skills named below. Read their current "
        "files directly and follow them as the authoritative workflow sources.\n"
        f"{upstream_sources or '- No upstream phase skill is required for an empty queue.'}\n\n"
        f"{action}\n\n{snapshot_text}\n\n"
        "The development PC is the coordinator. Delegate only server-local investigation or "
        "execution through $server-codex-task, retrieve its result, and continue the same ticket."
    )


def build_codex_command(
    config: AutopilotConfig,
    final_message: Path,
    dry_run: bool = False,
) -> list[str]:
    command = [
        *config.codex_command,
        "exec",
        "--ephemeral",
        "--json",
        "--color",
        "never",
    ]
    if dry_run:
        command.extend(["--sandbox", "read-only"])
    else:
        command.extend(
            [
                "--approve-for-me",
                "--add-dir",
                str(config.worktree_root),
                "--config",
                "sandbox_workspace_write.network_access=true",
            ]
        )
    command.extend(["--cd", str(config.workspace), "-o", str(final_message), "-"])
    return command


def github_token(runner=subprocess.run) -> str:
    completed = runner(
        ["gh", "auth", "token"], capture_output=True, text=True, check=False
    )
    token = completed.stdout.strip()
    if completed.returncode or not token:
        raise RuntimeError("GitHub CLI authentication is unavailable; run gh auth login")
    return token


VIEWER_QUERY = "query { viewer { login } }"

ISSUE_PARENT_QUERY = """
query($id: ID!) {
  node(id: $id) {
    ... on Issue {
      parent { number title url repository { nameWithOwner } }
    }
  }
}
""".strip()


def _run_json(command: list[str], environment: dict[str, str], runner) -> object:
    completed = runner(
        command,
        capture_output=True,
        text=True,
        check=False,
        env=environment,
    )
    if completed.returncode:
        raise RuntimeError(completed.stderr.strip() or "GitHub queue snapshot failed")
    return json.loads(completed.stdout)


def _flatten_pages(value: object) -> list[dict]:
    if not isinstance(value, list):
        raise ValueError("paginated GitHub response must be a list")
    flattened = []
    for page in value:
        if not isinstance(page, list):
            raise ValueError("paginated GitHub response page must be a list")
        flattened.extend(page)
    return flattened


def _repository_from_issue_response(issue: dict) -> str:
    repository_url = issue.get("repository_url", "")
    marker = "/repos/"
    if marker in repository_url:
        return repository_url.split(marker, 1)[1]
    html_parts = issue.get("html_url", "").split("/")
    if len(html_parts) >= 5 and html_parts[2] == "github.com":
        return f"{html_parts[3]}/{html_parts[4]}"
    raise ValueError(f"issue #{issue.get('number')} has no resolvable repository URL")


def load_issue_details(
    summary: dict,
    environment: dict[str, str],
    runner=subprocess.run,
) -> dict:
    repository = summary["repository"]["nameWithOwner"]
    number = summary["number"]
    endpoint = f"repos/{repository}/issues/{number}"
    core = _run_json(["gh", "api", endpoint], environment, runner)
    comments = _flatten_pages(
        _run_json(
            ["gh", "api", "--paginate", "--slurp", f"{endpoint}/comments?per_page=100"],
            environment,
            runner,
        )
    )
    blockers = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                f"{endpoint}/dependencies/blocked_by?per_page=100",
            ],
            environment,
            runner,
        )
    )
    timeline = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                "-H",
                "Accept: application/vnd.github+json",
                f"{endpoint}/timeline?per_page=100",
            ],
            environment,
            runner,
        )
    )
    parent_result = _run_json(
        [
            "gh",
            "api",
            "graphql",
            "-f",
            f"query={ISSUE_PARENT_QUERY}",
            "-f",
            f"id={core['node_id']}",
        ],
        environment,
        runner,
    )
    claim_comments = [
        {
            "body": comment.get("body", ""),
            "author": {"login": (comment.get("user") or {}).get("login")},
            "createdAt": comment.get("created_at"),
        }
        for comment in comments
        if "<!-- wayfinder-autopilot-" in comment.get("body", "")
    ]
    linked_prs = []
    for event in timeline:
        if event.get("event") != "cross-referenced":
            continue
        source_issue = (event.get("source") or {}).get("issue") or {}
        if "pull_request" not in source_issue:
            continue
        linked_prs.append(
            {
                "number": source_issue.get("number"),
                "state": source_issue.get("state", "").upper(),
                "url": source_issue.get("html_url"),
                "repository": {
                    "nameWithOwner": (source_issue.get("repository") or {}).get("full_name")
                },
            }
        )
    return {
        "number": core["number"],
        "title": core["title"],
        "state": core["state"].upper(),
        "body": core.get("body") or "",
        "url": core["html_url"],
        "createdAt": core["created_at"],
        "updatedAt": core["updated_at"],
        "repository": {"nameWithOwner": repository},
        "assignees": {
            "nodes": [{"login": assignee["login"]} for assignee in core.get("assignees", [])]
        },
        "labels": {"nodes": [{"name": label["name"]} for label in core.get("labels", [])]},
        "blockedBy": {
            "nodes": [
                {
                    "number": blocker["number"],
                    "state": blocker["state"].upper(),
                    "repository": {
                        "nameWithOwner": _repository_from_issue_response(blocker)
                    },
                }
                for blocker in blockers
            ]
        },
        "comments": {"nodes": claim_comments},
        "linkedPullRequests": linked_prs,
        "parent": parent_result["data"]["node"]["parent"],
    }


def load_queue_snapshot(
    config: AutopilotConfig,
    token: str,
    runner=subprocess.run,
    detail_loader=None,
) -> dict:
    environment = dict(os.environ)
    environment["GH_TOKEN"] = token
    viewer_result = _run_json(
        ["gh", "api", "graphql", "-f", f"query={VIEWER_QUERY}"],
        environment,
        runner,
    )
    viewer = viewer_result["data"]["viewer"]["login"]
    repositories_by_name = {}
    for scope in config.queue_scopes:
        owner = scope.split(":", 1)[1]
        repositories = _run_json(
            [
                "gh",
                "repo",
                "list",
                owner,
                "--limit",
                "100000",
                "--json",
                "nameWithOwner,isArchived,hasIssuesEnabled",
            ],
            environment,
            runner,
        )
        for repository in repositories:
            if not repository["isArchived"] and repository["hasIssuesEnabled"]:
                repositories_by_name[repository["nameWithOwner"]] = repository

    summaries_by_url = {}
    for repository_name in sorted(repositories_by_name, key=str.lower):
        commands = [
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--assignee", viewer, "--limit", "100000", "--json", "number,url,createdAt",
            ],
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--label", "ready-for-agent", "--limit", "100000", "--json", "number,url,createdAt",
            ],
        ]
        for command in commands:
            for summary in _run_json(command, environment, runner):
                summary["repository"] = {"nameWithOwner": repository_name}
                summaries_by_url[summary["url"]] = summary

    loader = detail_loader or (
        lambda summary: load_issue_details(summary, environment, runner=runner)
    )
    issues = []
    for summary in summaries_by_url.values():
        issue = loader(summary)
        labels = {label["name"] for label in issue["labels"]["nodes"]}
        has_current_claim = any(
            comment.get("author", {}).get("login") == viewer
            and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
            for comment in issue["comments"]["nodes"]
        )
        if "ready-for-agent" in labels or has_current_claim:
            issues.append(issue)
    issues.sort(
        key=lambda issue: (
            issue.get("createdAt", ""),
            issue["repository"]["nameWithOwner"].lower(),
            issue["number"],
        )
    )
    return {
        "viewer": {"login": viewer},
        "scopes": config.queue_scopes,
        "ordering": "createdAt ascending, then repository name, then issue number",
        "issues": issues,
    }


def build_environment(
    config: AutopilotConfig,
    token: str | None,
    base: dict[str, str] | None = None,
) -> dict[str, str]:
    environment = dict(os.environ if base is None else base)
    environment["WAYFINDER_WORKSPACE_ROOT"] = str(config.workspace)
    environment["WAYFINDER_WORKTREE_ROOT"] = str(config.worktree_root)
    environment["WAYFINDER_QUEUE_SCOPES"] = json.dumps(config.queue_scopes)
    environment["WAYFINDER_CONTROL_REPOSITORY"] = config.control_repository
    environment["WAYFINDER_TRUSTED_REPOSITORY_ROOTS"] = json.dumps(
        [str(root) for root in config.trusted_repository_roots]
    )
    environment.pop("GH_TOKEN", None)
    environment.pop("GITHUB_TOKEN", None)
    if token is not None:
        environment["GH_TOKEN"] = token
    environment["GIT_CONFIG_COUNT"] = "2"
    environment["GIT_CONFIG_KEY_0"] = "credential.helper"
    environment["GIT_CONFIG_VALUE_0"] = ""
    environment["GIT_CONFIG_KEY_1"] = "credential.https://github.com.helper"
    environment["GIT_CONFIG_VALUE_1"] = "!gh auth git-credential"
    return environment


def _element(parent: ET.Element, name: str, text: str | None = None) -> ET.Element:
    child = ET.SubElement(parent, f"{{{TASK_XML_NS}}}{name}")
    if text is not None:
        child.text = text
    return child


def render_task_xml(config: AutopilotConfig, user_id: str) -> str:
    ET.register_namespace("", TASK_XML_NS)
    task = ET.Element(f"{{{TASK_XML_NS}}}Task", {"version": "1.4"})
    registration = _element(task, "RegistrationInfo")
    _element(registration, "Description", "Advance trusted Wayfinder work with Codex")
    triggers = _element(task, "Triggers")
    calendar = _element(triggers, "CalendarTrigger")
    repetition = _element(calendar, "Repetition")
    _element(repetition, "Interval", f"PT{config.interval_minutes}M")
    _element(repetition, "Duration", "P1D")
    _element(repetition, "StopAtDurationEnd", "false")
    _element(calendar, "StartBoundary", (datetime.now().astimezone() + timedelta(minutes=1)).isoformat(timespec="seconds"))
    _element(calendar, "Enabled", "true")
    schedule = _element(calendar, "ScheduleByDay")
    _element(schedule, "DaysInterval", "1")
    principals = _element(task, "Principals")
    principal = _element(principals, "Principal")
    principal.set("id", "Author")
    _element(principal, "UserId", user_id)
    _element(principal, "LogonType", "InteractiveToken")
    _element(principal, "RunLevel", "LeastPrivilege")
    settings = _element(task, "Settings")
    _element(settings, "MultipleInstancesPolicy", "IgnoreNew")
    _element(settings, "DisallowStartIfOnBatteries", "false")
    _element(settings, "StopIfGoingOnBatteries", "false")
    _element(settings, "StartWhenAvailable", "true")
    _element(settings, "AllowHardTerminate", "true")
    scheduler_timeout = config.timeout_seconds + SCHEDULER_CLEANUP_GRACE_SECONDS
    hours, remainder = divmod(scheduler_timeout, 3600)
    minutes, seconds = divmod(remainder, 60)
    duration = "PT"
    if hours:
        duration += f"{hours}H"
    if minutes:
        duration += f"{minutes}M"
    if seconds or duration == "PT":
        duration += f"{seconds}S"
    _element(settings, "ExecutionTimeLimit", duration)
    actions = _element(task, "Actions")
    actions.set("Context", "Author")
    execute = _element(actions, "Exec")
    _element(execute, "Command", os.environ.get("ComSpec", r"C:\Windows\System32\cmd.exe"))
    entrypoint = config.workspace / "scripts" / "wayfinder-autopilot.cmd"
    _element(execute, "Arguments", f'/d /c ""{entrypoint}" run"')
    _element(execute, "WorkingDirectory", str(config.workspace))
    return ET.tostring(task, encoding="unicode")


def _terminate_process_tree(process: subprocess.Popen) -> None:
    if os.name == "nt":
        subprocess.run(
            ["taskkill", "/PID", str(process.pid), "/T", "/F"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
    else:
        process.kill()


def run_once(
    config: AutopilotConfig,
    dry_run: bool = False,
    token_provider=github_token,
    snapshot_provider=load_queue_snapshot,
) -> dict:
    config.log_dir.mkdir(parents=True, exist_ok=True)
    if not dry_run:
        config.worktree_root.mkdir(parents=True, exist_ok=True)
    with RunLock(config.log_dir / "run.lock") as lock:
        if not lock.acquired:
            return {"state": "overlap", "message": "another Wayfinder autopilot run is active"}
        run_id = datetime.now().strftime("%Y%m%dT%H%M%S-%f")
        run_dir = config.log_dir / "runs" / run_id
        run_dir.mkdir(parents=True)
        events_path = run_dir / "events.jsonl"
        stderr_path = run_dir / "stderr.log"
        final_path = run_dir / "final.md"
        metadata_path = run_dir / "run.json"
        metadata = {
            "run_id": run_id,
            "state": "running",
            "dry_run": dry_run,
            "started_at": datetime.now().astimezone().isoformat(),
            "workspace": str(config.workspace),
        }
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        exit_code = None
        process = None
        try:
            token = token_provider()
            snapshot = snapshot_provider(config, token)
            route = select_snapshot_route(snapshot)
            require_upstream_skill_files(config, route_skill_names(route))
            environment = build_environment(config, None if dry_run else token)
            command = build_codex_command(config, final_path, dry_run=dry_run)
            with events_path.open("w", encoding="utf-8") as events, stderr_path.open("w", encoding="utf-8") as errors:
                process = subprocess.Popen(
                    command,
                    cwd=config.workspace,
                    env=environment,
                    stdin=subprocess.PIPE,
                    stdout=events,
                    stderr=errors,
                    text=True,
                )
                process.communicate(
                    build_prompt(config, dry_run=dry_run, queue_snapshot=snapshot),
                    timeout=config.timeout_seconds,
                )
                exit_code = process.returncode
                state = "completed" if process.returncode == 0 else "failed"
        except subprocess.TimeoutExpired:
            if process is not None:
                _terminate_process_tree(process)
                process.wait()
                exit_code = process.returncode
            state = "timed_out"
        except (OSError, RuntimeError, ValueError) as exc:
            state = "failed"
            metadata["error"] = str(exc)
        metadata.update(
            state=state,
            exit_code=exit_code,
            finished_at=datetime.now().astimezone().isoformat(),
        )
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        return {
            "state": state,
            "run_id": run_id,
            "events": str(events_path),
            "stderr": str(stderr_path),
            "final_message": str(final_path),
            "metadata": str(metadata_path),
        }


def install(
    config: AutopilotConfig,
    skill_destination: Path,
    user_id: str,
    runner=subprocess.run,
) -> dict:
    if os.name != "nt":
        raise RuntimeError("Wayfinder autopilot installation currently supports Windows only")
    if not (config.skill_source / "SKILL.md").is_file():
        raise FileNotFoundError(f"skill source is incomplete: {config.skill_source}")
    skill_destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(config.skill_source, skill_destination, dirs_exist_ok=True)
    xml = render_task_xml(config, user_id)
    temporary_path: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-16", suffix=".xml", delete=False
        ) as handle:
            handle.write(xml)
            temporary_path = Path(handle.name)
        command = ["schtasks", "/Create", "/TN", TASK_NAME, "/XML", str(temporary_path), "/F"]
        completed = runner(command, capture_output=True, text=True, check=False)
        if completed.returncode:
            raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    finally:
        if temporary_path is not None and temporary_path.is_file():
            temporary_path.unlink()
    return {"state": "installed", "task": TASK_NAME, "skill": str(skill_destination)}


def remove(
    skill_destination: Path,
    skills_root: Path,
    runner=subprocess.run,
) -> dict:
    destination = skill_destination.resolve()
    root = skills_root.resolve()
    if destination.parent != root or destination.name != "wayfinder-autopilot":
        raise ValueError(f"refusing to remove unexpected skill path: {destination}")
    completed = runner(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        check=False,
    )
    if completed.returncode and "cannot find" not in completed.stderr.lower():
        raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    if destination.is_dir():
        shutil.rmtree(destination)
    return {"state": "removed", "task": TASK_NAME, "skill": str(destination)}


def task_status(runner=subprocess.run) -> dict:
    completed = runner(
        ["schtasks", "/Query", "/TN", TASK_NAME, "/FO", "LIST", "/V"],
        capture_output=True,
        text=True,
        check=False,
    )
    return {
        "state": "installed" if completed.returncode == 0 else "not_installed",
        "task": TASK_NAME,
        "details": completed.stdout.strip() or completed.stderr.strip(),
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--config", type=Path)
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("run")
    subparsers.add_parser("dry-run")
    subparsers.add_parser("install")
    subparsers.add_parser("status")
    subparsers.add_parser("uninstall")
    history_parser = subparsers.add_parser("history")
    history_parser.add_argument("--limit", type=int, default=None)
    history_parser.add_argument("--state", action="append", default=None)
    return parser


def list_runs(config: AutopilotConfig, *, limit: int | None = None, states: list[str] | None = None) -> dict:
    runs_dir = config.log_dir / HISTORY_RUNS_DIR
    entries: list[dict] = []
    if runs_dir.is_dir():
        for child in runs_dir.iterdir():
            if not child.is_dir():
                continue
            metadata_path = child / "run.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                entries.append({
                    "run_id": child.name,
                    "state": "unreadable",
                    "dry_run": None,
                    "started_at": None,
                    "finished_at": None,
                    "duration_seconds": None,
                    "exit_code": None,
                    "error": "failed to parse run.json",
                    "events": None,
                    "stderr": None,
                    "final_message": None,
                    "metadata": str(metadata_path),
                })
                continue
            started = metadata.get("started_at")
            finished = metadata.get("finished_at")
            duration: float | None = None
            if started and finished:
                try:
                    start_dt = datetime.fromisoformat(started)
                    finish_dt = datetime.fromisoformat(finished)
                    duration = round((finish_dt - start_dt).total_seconds(), 3)
                except (ValueError, TypeError):
                    pass
            is_abandoned = False
            if metadata.get("state") == "running" and started:
                try:
                    start_dt = datetime.fromisoformat(started)
                    elapsed = (datetime.now().astimezone() - start_dt).total_seconds()
                    if elapsed > SCHEDULER_CLEANUP_GRACE_SECONDS:
                        is_abandoned = True
                except (ValueError, TypeError):
                    pass
            entry = {
                "run_id": metadata.get("run_id", child.name),
                "state": metadata.get("state", "unknown"),
                "dry_run": metadata.get("dry_run"),
                "started_at": started,
                "finished_at": finished,
                "duration_seconds": duration,
                "exit_code": metadata.get("exit_code"),
                "error": metadata.get("error"),
                "abandoned": is_abandoned,
                "events": child.joinpath("events.jsonl") if (child / "events.jsonl").is_file() else None,
                "stderr": child.joinpath("stderr.log") if (child / "stderr.log").is_file() else None,
                "final_message": child.joinpath("final.md") if (child / "final.md").is_file() else None,
                "metadata": str(metadata_path),
            }
            entries.append(entry)
    # run_id is fixed-width timestamp, so lexicographic reverse == newest first
    entries.sort(key=lambda e: e["run_id"], reverse=True)
    if states:
        entries = [e for e in entries if e["state"] in states]
    if limit is not None:
        entries = entries[:limit]
    return {"state": HISTORY_STATE_OK, "runs": entries}


def main() -> int:
    args = build_parser().parse_args()
    try:
        config = AutopilotConfig.load(args.workspace, args.config)
        codex_home = Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
        skills_root = codex_home / "skills"
        skill_destination = skills_root / "wayfinder-autopilot"
        if args.command in {"run", "dry-run"}:
            result = run_once(config, dry_run=args.command == "dry-run")
        elif args.command == "install":
            user = subprocess.run(
                ["whoami"], capture_output=True, text=True, check=True
            ).stdout.strip()
            result = install(config, skill_destination, user)
        elif args.command == "status":
            result = task_status()
            result["log_dir"] = str(config.log_dir)
            result["skill"] = str(skill_destination)
        elif args.command == "history":
            states = sorted(args.state) if args.state else None
            result = list_runs(config, limit=args.limit, states=states)
        else:
            result = remove(skill_destination, skills_root)
        print(json.dumps(result, indent=2))
        return 0 if result["state"] not in {"failed", "timed_out"} else 1
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError, subprocess.CalledProcessError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Run and install the development-PC Wayfinder Codex coordinator."""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timedelta
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
from typing import IO
import xml.etree.ElementTree as ET

if os.name == "nt":
    import msvcrt


TASK_NAME = "Codex Wayfinder Autopilot"
TASK_XML_NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"
SCHEDULER_CLEANUP_GRACE_SECONDS = 300
QUEUE_SCOPE_PATTERN = re.compile(r"^(?:user|org):[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$")
HISTORY_RUNS_DIR = "runs"
HISTORY_STATE_OK = "ok"


@dataclass
class AutopilotConfig:
    workspace: Path
    worktree_root: Path
    log_dir: Path
    skill_source: Path
    codex_command: list[str]
    queue_scopes: list[str]
    control_repository: str
    trusted_repository_roots: list[Path]
    upstream_skills_root: Path | None = None
    interval_minutes: int = 15
    timeout_seconds: int = 14_400

    @classmethod
    def load(cls, workspace: Path, config_path: Path | None = None) -> "AutopilotConfig":
        workspace = workspace.resolve()
        path = config_path or workspace / "config" / "wayfinder-autopilot.json"
        with path.open("r", encoding="utf-8") as handle:
            raw = json.load(handle)
        worktree_root = Path(raw.get("worktree_root", "../homelab-worktrees"))
        if not worktree_root.is_absolute():
            worktree_root = workspace / worktree_root
        local_app_data = Path(os.environ.get("LOCALAPPDATA", tempfile.gettempdir()))
        log_dir = Path(raw.get("log_dir", local_app_data / "Codex" / "wayfinder-autopilot"))
        if not log_dir.is_absolute():
            log_dir = workspace / log_dir
        command = raw.get("codex_command", ["codex.cmd"])
        if not isinstance(command, list) or not all(isinstance(item, str) for item in command):
            raise ValueError("codex_command must be a list of strings")
        queue_scopes = raw.get("queue_scopes")
        if (
            not isinstance(queue_scopes, list)
            or not queue_scopes
            or not all(isinstance(scope, str) and QUEUE_SCOPE_PATTERN.fullmatch(scope) for scope in queue_scopes)
        ):
            raise ValueError("each queue scope must be user:<owner> or org:<owner>")
        control_repository = raw.get("control_repository")
        if not isinstance(control_repository, str) or control_repository.count("/") != 1:
            raise ValueError("control_repository must be an owner/repository name")
        trusted_roots = raw.get("trusted_repository_roots", ["repos"])
        if not isinstance(trusted_roots, list) or not all(isinstance(root, str) for root in trusted_roots):
            raise ValueError("trusted_repository_roots must be a list of paths")
        return cls(
            workspace=workspace,
            worktree_root=worktree_root.resolve(),
            log_dir=log_dir.resolve(),
            skill_source=workspace / "skills" / "wayfinder-autopilot",
            codex_command=command,
            queue_scopes=queue_scopes,
            control_repository=control_repository,
            trusted_repository_roots=[
                (workspace / root).resolve() if not Path(root).is_absolute() else Path(root).resolve()
                for root in trusted_roots
            ],
            upstream_skills_root=(
                Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
                / "skills"
            ),
            interval_minutes=int(raw.get("interval_minutes", 15)),
            timeout_seconds=int(raw.get("timeout_seconds", 14_400)),
        )


def upstream_skill_paths(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    root = config.upstream_skills_root or (
        Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve() / "skills"
    )
    return {name: root / name / "SKILL.md" for name in names}


def require_upstream_skill_files(
    config: AutopilotConfig, names: tuple[str, ...]
) -> dict[str, Path]:
    paths = upstream_skill_paths(config, names)
    invalid = []
    for name, path in paths.items():
        try:
            source = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            invalid.append(name)
            continue
        frontmatter = re.match(r"\A---\s*\n(.*?)\n---\s*\n(.+)\Z", source, re.DOTALL)
        if not frontmatter or not re.search(
            rf"^name:\s*[\"']?{re.escape(name)}[\"']?\s*$",
            frontmatter.group(1),
            re.MULTILINE,
        ):
            invalid.append(name)
    if invalid:
        raise RuntimeError(
            "required upstream Matt Pocock skills are unavailable or invalid: "
            + ", ".join(invalid)
        )
    return paths


def _issue_route(issue: dict) -> str:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    if any(pr.get("state") == "OPEN" for pr in issue.get("linkedPullRequests", [])):
        return "review"
    return "research" if "wayfinder:research" in labels else "task"


def _has_ticket_contract(issue: dict) -> bool:
    body = issue.get("body", "")
    for heading in ("Outcome", "Completion criteria"):
        section = re.search(
            rf"^## {re.escape(heading)}\s*$\n(.*?)(?=^## |\Z)",
            body,
            re.MULTILINE | re.DOTALL,
        )
        if not section or not section.group(1).strip():
            return False
    return True


def _issue_facts(issue: dict, viewer: str | None) -> dict:
    labels = {node["name"] for node in issue.get("labels", {}).get("nodes", [])}
    assignees = {
        node["login"] for node in issue.get("assignees", {}).get("nodes", [])
    }
    markers = [
        comment.get("createdAt") or ""
        for comment in issue.get("comments", {}).get("nodes", [])
        if comment.get("author", {}).get("login") == viewer
        and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
    ]
    return {
        "labels": labels,
        "assignees": assignees,
        "markers": markers,
        "typed": bool(labels & {"wayfinder:research", "wayfinder:task"}),
        "blockers_closed": all(
            blocker.get("state") == "CLOSED"
            for blocker in issue.get("blockedBy", {}).get("nodes", [])
        ),
        "contract": _has_ticket_contract(issue),
    }


def select_snapshot_route(snapshot: dict) -> dict | None:
    viewer = snapshot.get("viewer", {}).get("login")
    issues = snapshot.get("issues", [])

    resumable = []
    for index, issue in enumerate(issues):
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and facts["typed"]
            and "ready-for-human" not in facts["labels"]
            and facts["markers"]
        ):
            resumable.append((min(facts["markers"]), index, issue))
    if resumable:
        issue = min(resumable, key=lambda item: (item[0], item[1]))[2]
        return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and viewer in facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and not facts["markers"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}

    for issue in issues:
        facts = _issue_facts(issue, viewer)
        if (
            issue.get("state") == "OPEN"
            and not facts["assignees"]
            and "ready-for-agent" in facts["labels"]
            and "ready-for-human" not in facts["labels"]
            and facts["typed"]
            and facts["blockers_closed"]
            and facts["contract"]
        ):
            return {"issue": issue["url"], "phase": _issue_route(issue)}
    return None


def route_skill_names(route: dict | None) -> tuple[str, ...]:
    if route is None:
        return ()
    if route["phase"] == "research":
        return ("wayfinder", "research")
    if route["phase"] == "review":
        return ("wayfinder", "code-review", "implement", "tdd")
    return ("wayfinder", "implement", "tdd")


class RunLock:
    """A process-held Windows byte lock that cannot become stale."""

    def __init__(self, path: Path):
        self.path = path
        self.handle: IO[bytes] | None = None
        self.acquired = False

    def __enter__(self) -> "RunLock":
        if os.name != "nt":
            raise RuntimeError("Wayfinder autopilot currently supports Windows only")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.handle = self.path.open("a+b")
        self.handle.seek(0, os.SEEK_END)
        if self.handle.tell() == 0:
            self.handle.write(b"0")
            self.handle.flush()
        self.handle.seek(0)
        try:
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_NBLCK, 1)
            self.acquired = True
        except OSError:
            self.acquired = False
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        if self.handle is None:
            return
        if self.acquired:
            self.handle.seek(0)
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_UNLCK, 1)
        self.handle.close()


def build_prompt(
    config: AutopilotConfig,
    dry_run: bool = False,
    queue_snapshot: dict | None = None,
) -> str:
    route = select_snapshot_route(queue_snapshot or {})
    upstream = upstream_skill_paths(config, route_skill_names(route))
    upstream_sources = "\n".join(
        f"- ${name}: {path}" for name, path in upstream.items()
    )
    snapshot_text = f"QUEUE_SNAPSHOT_JSON\n{json.dumps(queue_snapshot, indent=2)}"
    if dry_run:
        action = (
            "Perform a read-only queue dry run. Identify the work item that would be processed "
            "and explain why it is eligible. Do not assign or unassign issues, do not edit labels, "
            "branches, files, pull requests, or parent maps, and do not dispatch server work. "
            "Do not access GitHub or the network; use only the live read-only queue snapshot below."
        )
    else:
        action = (
            "Advance exactly one autonomous unit of work from the exhaustive queue snapshot below. "
            "Treat it as authoritative for discovery and ordering; revalidate only the selected issue "
            "against live GitHub before mutation. Prefer completing review, CI repair, and merge for "
            "an already claimed item before claiming new work."
        )
    return (
        f"Use $wayfinder-autopilot across GitHub scopes {', '.join(config.queue_scopes)}. "
        "Its canonical source is "
        f"{config.skill_source / 'SKILL.md'}; read that authoritative file before acting.\n\n"
        f"PRESELECTED_ROUTE_JSON\n{json.dumps(route, indent=2)}\n\n"
        "Use only the installed upstream Matt Pocock skills named below. Read their current "
        "files directly and follow them as the authoritative workflow sources.\n"
        f"{upstream_sources or '- No upstream phase skill is required for an empty queue.'}\n\n"
        f"{action}\n\n{snapshot_text}\n\n"
        "The development PC is the coordinator. Delegate only server-local investigation or "
        "execution through $server-codex-task, retrieve its result, and continue the same ticket."
    )


def build_codex_command(
    config: AutopilotConfig,
    final_message: Path,
    dry_run: bool = False,
) -> list[str]:
    command = [
        *config.codex_command,
        "exec",
        "--ephemeral",
        "--json",
        "--color",
        "never",
    ]
    if dry_run:
        command.extend(["--sandbox", "read-only"])
    else:
        command.extend(
            [
                "--approve-for-me",
                "--add-dir",
                str(config.worktree_root),
                "--config",
                "sandbox_workspace_write.network_access=true",
            ]
        )
    command.extend(["--cd", str(config.workspace), "-o", str(final_message), "-"])
    return command


def github_token(runner=subprocess.run) -> str:
    completed = runner(
        ["gh", "auth", "token"], capture_output=True, text=True, check=False
    )
    token = completed.stdout.strip()
    if completed.returncode or not token:
        raise RuntimeError("GitHub CLI authentication is unavailable; run gh auth login")
    return token


VIEWER_QUERY = "query { viewer { login } }"

ISSUE_PARENT_QUERY = """
query($id: ID!) {
  node(id: $id) {
    ... on Issue {
      parent { number title url repository { nameWithOwner } }
    }
  }
}
""".strip()


def _run_json(command: list[str], environment: dict[str, str], runner) -> object:
    completed = runner(
        command,
        capture_output=True,
        text=True,
        check=False,
        env=environment,
    )
    if completed.returncode:
        raise RuntimeError(completed.stderr.strip() or "GitHub queue snapshot failed")
    return json.loads(completed.stdout)


def _flatten_pages(value: object) -> list[dict]:
    if not isinstance(value, list):
        raise ValueError("paginated GitHub response must be a list")
    flattened = []
    for page in value:
        if not isinstance(page, list):
            raise ValueError("paginated GitHub response page must be a list")
        flattened.extend(page)
    return flattened


def _repository_from_issue_response(issue: dict) -> str:
    repository_url = issue.get("repository_url", "")
    marker = "/repos/"
    if marker in repository_url:
        return repository_url.split(marker, 1)[1]
    html_parts = issue.get("html_url", "").split("/")
    if len(html_parts) >= 5 and html_parts[2] == "github.com":
        return f"{html_parts[3]}/{html_parts[4]}"
    raise ValueError(f"issue #{issue.get('number')} has no resolvable repository URL")


def load_issue_details(
    summary: dict,
    environment: dict[str, str],
    runner=subprocess.run,
) -> dict:
    repository = summary["repository"]["nameWithOwner"]
    number = summary["number"]
    endpoint = f"repos/{repository}/issues/{number}"
    core = _run_json(["gh", "api", endpoint], environment, runner)
    comments = _flatten_pages(
        _run_json(
            ["gh", "api", "--paginate", "--slurp", f"{endpoint}/comments?per_page=100"],
            environment,
            runner,
        )
    )
    blockers = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                f"{endpoint}/dependencies/blocked_by?per_page=100",
            ],
            environment,
            runner,
        )
    )
    timeline = _flatten_pages(
        _run_json(
            [
                "gh",
                "api",
                "--paginate",
                "--slurp",
                "-H",
                "Accept: application/vnd.github+json",
                f"{endpoint}/timeline?per_page=100",
            ],
            environment,
            runner,
        )
    )
    parent_result = _run_json(
        [
            "gh",
            "api",
            "graphql",
            "-f",
            f"query={ISSUE_PARENT_QUERY}",
            "-f",
            f"id={core['node_id']}",
        ],
        environment,
        runner,
    )
    claim_comments = [
        {
            "body": comment.get("body", ""),
            "author": {"login": (comment.get("user") or {}).get("login")},
            "createdAt": comment.get("created_at"),
        }
        for comment in comments
        if "<!-- wayfinder-autopilot-" in comment.get("body", "")
    ]
    linked_prs = []
    for event in timeline:
        if event.get("event") != "cross-referenced":
            continue
        source_issue = (event.get("source") or {}).get("issue") or {}
        if "pull_request" not in source_issue:
            continue
        linked_prs.append(
            {
                "number": source_issue.get("number"),
                "state": source_issue.get("state", "").upper(),
                "url": source_issue.get("html_url"),
                "repository": {
                    "nameWithOwner": (source_issue.get("repository") or {}).get("full_name")
                },
            }
        )
    return {
        "number": core["number"],
        "title": core["title"],
        "state": core["state"].upper(),
        "body": core.get("body") or "",
        "url": core["html_url"],
        "createdAt": core["created_at"],
        "updatedAt": core["updated_at"],
        "repository": {"nameWithOwner": repository},
        "assignees": {
            "nodes": [{"login": assignee["login"]} for assignee in core.get("assignees", [])]
        },
        "labels": {"nodes": [{"name": label["name"]} for label in core.get("labels", [])]},
        "blockedBy": {
            "nodes": [
                {
                    "number": blocker["number"],
                    "state": blocker["state"].upper(),
                    "repository": {
                        "nameWithOwner": _repository_from_issue_response(blocker)
                    },
                }
                for blocker in blockers
            ]
        },
        "comments": {"nodes": claim_comments},
        "linkedPullRequests": linked_prs,
        "parent": parent_result["data"]["node"]["parent"],
    }


def load_queue_snapshot(
    config: AutopilotConfig,
    token: str,
    runner=subprocess.run,
    detail_loader=None,
) -> dict:
    environment = dict(os.environ)
    environment["GH_TOKEN"] = token
    viewer_result = _run_json(
        ["gh", "api", "graphql", "-f", f"query={VIEWER_QUERY}"],
        environment,
        runner,
    )
    viewer = viewer_result["data"]["viewer"]["login"]
    repositories_by_name = {}
    for scope in config.queue_scopes:
        owner = scope.split(":", 1)[1]
        repositories = _run_json(
            [
                "gh",
                "repo",
                "list",
                owner,
                "--limit",
                "100000",
                "--json",
                "nameWithOwner,isArchived,hasIssuesEnabled",
            ],
            environment,
            runner,
        )
        for repository in repositories:
            if not repository["isArchived"] and repository["hasIssuesEnabled"]:
                repositories_by_name[repository["nameWithOwner"]] = repository

    summaries_by_url = {}
    for repository_name in sorted(repositories_by_name, key=str.lower):
        commands = [
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--assignee", viewer, "--limit", "100000", "--json", "number,url,createdAt",
            ],
            [
                "gh", "issue", "list", "--repo", repository_name, "--state", "open",
                "--label", "ready-for-agent", "--limit", "100000", "--json", "number,url,createdAt",
            ],
        ]
        for command in commands:
            for summary in _run_json(command, environment, runner):
                summary["repository"] = {"nameWithOwner": repository_name}
                summaries_by_url[summary["url"]] = summary

    loader = detail_loader or (
        lambda summary: load_issue_details(summary, environment, runner=runner)
    )
    issues = []
    for summary in summaries_by_url.values():
        issue = loader(summary)
        labels = {label["name"] for label in issue["labels"]["nodes"]}
        has_current_claim = any(
            comment.get("author", {}).get("login") == viewer
            and "<!-- wayfinder-autopilot-claim -->" in comment.get("body", "")
            for comment in issue["comments"]["nodes"]
        )
        if "ready-for-agent" in labels or has_current_claim:
            issues.append(issue)
    issues.sort(
        key=lambda issue: (
            issue.get("createdAt", ""),
            issue["repository"]["nameWithOwner"].lower(),
            issue["number"],
        )
    )
    return {
        "viewer": {"login": viewer},
        "scopes": config.queue_scopes,
        "ordering": "createdAt ascending, then repository name, then issue number",
        "issues": issues,
    }


def build_environment(
    config: AutopilotConfig,
    token: str | None,
    base: dict[str, str] | None = None,
) -> dict[str, str]:
    environment = dict(os.environ if base is None else base)
    environment["WAYFINDER_WORKSPACE_ROOT"] = str(config.workspace)
    environment["WAYFINDER_WORKTREE_ROOT"] = str(config.worktree_root)
    environment["WAYFINDER_QUEUE_SCOPES"] = json.dumps(config.queue_scopes)
    environment["WAYFINDER_CONTROL_REPOSITORY"] = config.control_repository
    environment["WAYFINDER_TRUSTED_REPOSITORY_ROOTS"] = json.dumps(
        [str(root) for root in config.trusted_repository_roots]
    )
    environment.pop("GH_TOKEN", None)
    environment.pop("GITHUB_TOKEN", None)
    if token is not None:
        environment["GH_TOKEN"] = token
    environment["GIT_CONFIG_COUNT"] = "2"
    environment["GIT_CONFIG_KEY_0"] = "credential.helper"
    environment["GIT_CONFIG_VALUE_0"] = ""
    environment["GIT_CONFIG_KEY_1"] = "credential.https://github.com.helper"
    environment["GIT_CONFIG_VALUE_1"] = "!gh auth git-credential"
    return environment


def _element(parent: ET.Element, name: str, text: str | None = None) -> ET.Element:
    child = ET.SubElement(parent, f"{{{TASK_XML_NS}}}{name}")
    if text is not None:
        child.text = text
    return child


def render_task_xml(config: AutopilotConfig, user_id: str) -> str:
    ET.register_namespace("", TASK_XML_NS)
    task = ET.Element(f"{{{TASK_XML_NS}}}Task", {"version": "1.4"})
    registration = _element(task, "RegistrationInfo")
    _element(registration, "Description", "Advance trusted Wayfinder work with Codex")
    triggers = _element(task, "Triggers")
    calendar = _element(triggers, "CalendarTrigger")
    repetition = _element(calendar, "Repetition")
    _element(repetition, "Interval", f"PT{config.interval_minutes}M")
    _element(repetition, "Duration", "P1D")
    _element(repetition, "StopAtDurationEnd", "false")
    _element(calendar, "StartBoundary", (datetime.now().astimezone() + timedelta(minutes=1)).isoformat(timespec="seconds"))
    _element(calendar, "Enabled", "true")
    schedule = _element(calendar, "ScheduleByDay")
    _element(schedule, "DaysInterval", "1")
    principals = _element(task, "Principals")
    principal = _element(principals, "Principal")
    principal.set("id", "Author")
    _element(principal, "UserId", user_id)
    _element(principal, "LogonType", "InteractiveToken")
    _element(principal, "RunLevel", "LeastPrivilege")
    settings = _element(task, "Settings")
    _element(settings, "MultipleInstancesPolicy", "IgnoreNew")
    _element(settings, "DisallowStartIfOnBatteries", "false")
    _element(settings, "StopIfGoingOnBatteries", "false")
    _element(settings, "StartWhenAvailable", "true")
    _element(settings, "AllowHardTerminate", "true")
    scheduler_timeout = config.timeout_seconds + SCHEDULER_CLEANUP_GRACE_SECONDS
    hours, remainder = divmod(scheduler_timeout, 3600)
    minutes, seconds = divmod(remainder, 60)
    duration = "PT"
    if hours:
        duration += f"{hours}H"
    if minutes:
        duration += f"{minutes}M"
    if seconds or duration == "PT":
        duration += f"{seconds}S"
    _element(settings, "ExecutionTimeLimit", duration)
    actions = _element(task, "Actions")
    actions.set("Context", "Author")
    execute = _element(actions, "Exec")
    _element(execute, "Command", os.environ.get("ComSpec", r"C:\Windows\System32\cmd.exe"))
    entrypoint = config.workspace / "scripts" / "wayfinder-autopilot.cmd"
    _element(execute, "Arguments", f'/d /c ""{entrypoint}" run"')
    _element(execute, "WorkingDirectory", str(config.workspace))
    return ET.tostring(task, encoding="unicode")


def _terminate_process_tree(process: subprocess.Popen) -> None:
    if os.name == "nt":
        subprocess.run(
            ["taskkill", "/PID", str(process.pid), "/T", "/F"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
    else:
        process.kill()


def run_once(
    config: AutopilotConfig,
    dry_run: bool = False,
    token_provider=github_token,
    snapshot_provider=load_queue_snapshot,
) -> dict:
    config.log_dir.mkdir(parents=True, exist_ok=True)
    if not dry_run:
        config.worktree_root.mkdir(parents=True, exist_ok=True)
    with RunLock(config.log_dir / "run.lock") as lock:
        if not lock.acquired:
            return {"state": "overlap", "message": "another Wayfinder autopilot run is active"}
        run_id = datetime.now().strftime("%Y%m%dT%H%M%S-%f")
        run_dir = config.log_dir / "runs" / run_id
        run_dir.mkdir(parents=True)
        events_path = run_dir / "events.jsonl"
        stderr_path = run_dir / "stderr.log"
        final_path = run_dir / "final.md"
        metadata_path = run_dir / "run.json"
        metadata = {
            "run_id": run_id,
            "state": "running",
            "dry_run": dry_run,
            "started_at": datetime.now().astimezone().isoformat(),
            "workspace": str(config.workspace),
        }
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        exit_code = None
        process = None
        try:
            token = token_provider()
            snapshot = snapshot_provider(config, token)
            route = select_snapshot_route(snapshot)
            require_upstream_skill_files(config, route_skill_names(route))
            environment = build_environment(config, None if dry_run else token)
            command = build_codex_command(config, final_path, dry_run=dry_run)
            with events_path.open("w", encoding="utf-8") as events, stderr_path.open("w", encoding="utf-8") as errors:
                process = subprocess.Popen(
                    command,
                    cwd=config.workspace,
                    env=environment,
                    stdin=subprocess.PIPE,
                    stdout=events,
                    stderr=errors,
                    text=True,
                )
                process.communicate(
                    build_prompt(config, dry_run=dry_run, queue_snapshot=snapshot),
                    timeout=config.timeout_seconds,
                )
                exit_code = process.returncode
                state = "completed" if process.returncode == 0 else "failed"
        except subprocess.TimeoutExpired:
            if process is not None:
                _terminate_process_tree(process)
                process.wait()
                exit_code = process.returncode
            state = "timed_out"
        except (OSError, RuntimeError, ValueError) as exc:
            state = "failed"
            metadata["error"] = str(exc)
        metadata.update(
            state=state,
            exit_code=exit_code,
            finished_at=datetime.now().astimezone().isoformat(),
        )
        metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        return {
            "state": state,
            "run_id": run_id,
            "events": str(events_path),
            "stderr": str(stderr_path),
            "final_message": str(final_path),
            "metadata": str(metadata_path),
        }


def install(
    config: AutopilotConfig,
    skill_destination: Path,
    user_id: str,
    runner=subprocess.run,
) -> dict:
    if os.name != "nt":
        raise RuntimeError("Wayfinder autopilot installation currently supports Windows only")
    if not (config.skill_source / "SKILL.md").is_file():
        raise FileNotFoundError(f"skill source is incomplete: {config.skill_source}")
    skill_destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(config.skill_source, skill_destination, dirs_exist_ok=True)
    xml = render_task_xml(config, user_id)
    temporary_path: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-16", suffix=".xml", delete=False
        ) as handle:
            handle.write(xml)
            temporary_path = Path(handle.name)
        command = ["schtasks", "/Create", "/TN", TASK_NAME, "/XML", str(temporary_path), "/F"]
        completed = runner(command, capture_output=True, text=True, check=False)
        if completed.returncode:
            raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    finally:
        if temporary_path is not None and temporary_path.is_file():
            temporary_path.unlink()
    return {"state": "installed", "task": TASK_NAME, "skill": str(skill_destination)}


def remove(
    skill_destination: Path,
    skills_root: Path,
    runner=subprocess.run,
) -> dict:
    destination = skill_destination.resolve()
    root = skills_root.resolve()
    if destination.parent != root or destination.name != "wayfinder-autopilot":
        raise ValueError(f"refusing to remove unexpected skill path: {destination}")
    completed = runner(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        check=False,
    )
    if completed.returncode and "cannot find" not in completed.stderr.lower():
        raise RuntimeError(completed.stderr.strip() or completed.stdout.strip())
    if destination.is_dir():
        shutil.rmtree(destination)
    return {"state": "removed", "task": TASK_NAME, "skill": str(destination)}


def task_status(runner=subprocess.run) -> dict:
    completed = runner(
        ["schtasks", "/Query", "/TN", TASK_NAME, "/FO", "LIST", "/V"],
        capture_output=True,
        text=True,
        check=False,
    )
    return {
        "state": "installed" if completed.returncode == 0 else "not_installed",
        "task": TASK_NAME,
        "details": completed.stdout.strip() or completed.stderr.strip(),
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--config", type=Path)
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("run")
    subparsers.add_parser("dry-run")
    subparsers.add_parser("install")
    subparsers.add_parser("status")
    subparsers.add_parser("uninstall")
    history_parser = subparsers.add_parser("history")
    history_parser.add_argument("--limit", type=int, default=None)
    history_parser.add_argument("--state", action="append", default=None)
    return parser


def list_runs(config: AutopilotConfig, *, limit: int | None = None, states: list[str] | None = None) -> dict:
    runs_dir = config.log_dir / HISTORY_RUNS_DIR
    entries: list[dict] = []
    if runs_dir.is_dir():
        for child in runs_dir.iterdir():
            if not child.is_dir():
                continue
            metadata_path = child / "run.json"
            try:
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                entries.append({
                    "run_id": child.name,
                    "state": "unreadable",
                    "dry_run": None,
                    "started_at": None,
                    "finished_at": None,
                    "duration_seconds": None,
                    "exit_code": None,
                    "error": "failed to parse run.json",
                    "events": None,
                    "stderr": None,
                    "final_message": None,
                    "metadata": str(metadata_path),
                })
                continue
            started = metadata.get("started_at")
            finished = metadata.get("finished_at")
            duration: float | None = None
            if started and finished:
                try:
                    start_dt = datetime.fromisoformat(started)
                    finish_dt = datetime.fromisoformat(finished)
                    duration = round((finish_dt - start_dt).total_seconds(), 3)
                except (ValueError, TypeError):
                    pass
            is_abandoned = False
            if metadata.get("state") == "running" and started:
                try:
                    start_dt = datetime.fromisoformat(started)
                    elapsed = (datetime.now().astimezone() - start_dt).total_seconds()
                    if elapsed > SCHEDULER_CLEANUP_GRACE_SECONDS:
                        is_abandoned = True
                except (ValueError, TypeError):
                    pass
            entry = {
                "run_id": metadata.get("run_id", child.name),
                "state": metadata.get("state", "unknown"),
                "dry_run": metadata.get("dry_run"),
                "started_at": started,
                "finished_at": finished,
                "duration_seconds": duration,
                "exit_code": metadata.get("exit_code"),
                "error": metadata.get("error"),
                "abandoned": is_abandoned,
                "events": child.joinpath("events.jsonl") if (child / "events.jsonl").is_file() else None,
                "stderr": child.joinpath("stderr.log") if (child / "stderr.log").is_file() else None,
                "final_message": child.joinpath("final.md") if (child / "final.md").is_file() else None,
                "metadata": str(metadata_path),
            }
            entries.append(entry)
    # run_id is fixed-width timestamp, so lexicographic reverse == newest first
    entries.sort(key=lambda e: e["run_id"], reverse=True)
    if states:
        entries = [e for e in entries if e["state"] in states]
    if limit is not None:
        entries = entries[:limit]
    return {"state": HISTORY_STATE_OK, "runs": entries}


def main() -> int:
    args = build_parser().parse_args()
    try:
        config = AutopilotConfig.load(args.workspace, args.config)
        codex_home = Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")).resolve()
        skills_root = codex_home / "skills"
        skill_destination = skills_root / "wayfinder-autopilot"
        if args.command in {"run", "dry-run"}:
            result = run_once(config, dry_run=args.command == "dry-run")
        elif args.command == "install":
            user = subprocess.run(
                ["whoami"], capture_output=True, text=True, check=True
            ).stdout.strip()
            result = install(config, skill_destination, user)
        elif args.command == "status":
            result = task_status()
            result["log_dir"] = str(config.log_dir)
            result["skill"] = str(skill_destination)
        elif args.command == "history":
            states = sorted(args.state) if args.state else None
            result = list_runs(config, limit=args.limit, states=states)
        else:
            result = remove(skill_destination, skills_root)
        print(json.dumps(result, indent=2))
        return 0 if result["state"] not in {"failed", "timed_out"} else 1
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError, subprocess.CalledProcessError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
